(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c70"]=[{"id":"00014096","register_sub_id":"101","register_pk":"508356","name":"鳥取家住宅新座敷","kana":"とっとりけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県三豊市豊中町笠田笠岡字五右衛門1764","lat":34.15260833,"lng":133.70632222,"geo_status":"db","era":"昭和前期／同後期・平成8年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺一部銅板葺、建築面積128㎡、石塀付","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"37 - 0451","desc":"主屋南に中庭を介して建つ座敷棟。二階建で北に八畳、西に洋館を付属する。一階続き間座敷は六尺に四枚建の猫間障子を周囲に建込む。洋館はパラペットを卵鏃帯で飾り、アーチ枠の窓は引違ガラス障子を建てる。細部の意匠も上質な洋館付近代和風住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014096"},{"id":"00014099","register_sub_id":"101","register_pk":"508359","name":"鳥取家住宅土蔵","kana":"とっとりけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県三豊市豊中町笠田笠岡字五右衛門1764","lat":34.15291111,"lng":133.70619444,"geo_status":"db","era":"明治39年／平成8年改修","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積66㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"37 - 0454","desc":"主屋北に東面して建つ南北棟土蔵。切妻造桟瓦葺で、東面に野物の桁と登り梁で庇を差掛ける。大棟両端は鬼瓦上に帆立瓦を飾る。東面に片引き戸の入口を二箇所設けるが、内部は一階、二階ともに一室とする。二階窓は鉄格子付。敷地北半の景観の要となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014099"},{"id":"00014102","register_sub_id":"101","register_pk":"508362","name":"鳥取家住宅西納屋","kana":"とっとりけじゅうたくにしなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県三豊市豊中町笠田笠岡字五右衛門1764","lat":34.152925,"lng":133.70610278,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"37 - 0457","desc":"土蔵の西の二階建で元は農具の倉庫。切妻造の南北棟で東に野物材で庇を差掛ける。外壁は真壁造中塗仕上。入口は開放とし、一階は南北に仕切り、二階は一室とする。小屋組は二重梁の和小屋で間に登梁が入り、竹野地を現しとする。敷地西方の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014102"},{"id":"00014106","register_sub_id":"101","register_pk":"508366","name":"鳥取家住宅西門","kana":"とっとりけじゅうたくにしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県三豊市豊中町笠田笠岡字五右衛門1764-1","lat":34.15261944,"lng":133.70619167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、鉄板葺、間口1.3m、袖塀付","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"37 - 0461","desc":"裏座敷の西庭の南辺に開く門。柱上部の腕木で軒桁を支え、屋根を鉄板葺とし、門口には両開きの網代戸を吊る。門の両脇に東西に延びる袖塀は、基礎を青石の乱積みとした竹穂垣で、西は温室に取付き、東は石塀に至る。多彩な造形で庭園の景観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014106"},{"id":"00014103","register_sub_id":"101","register_pk":"508363","name":"鳥取家住宅東納屋","kana":"とっとりけじゅうたくひがしなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県三豊市豊中町笠田笠岡字五右衛門1764","lat":34.15276944,"lng":133.70650556,"geo_status":"db","era":"明治27年／昭和前期増築、平成8年改修","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"37 - 0458","desc":"主屋の南東に建つ二階建納屋。切妻造南北棟で西正面の庇と共に当初の本瓦葺を残す。南に平屋の鶏小屋が付く。外壁は漆喰塗。入口は西面二箇所で、片引き板戸と亀甲銅網入り板戸を建込む。窓は正面二階の二箇所で無双連子を入れる。敷地東方の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014103"},{"id":"00014105","register_sub_id":"101","register_pk":"508365","name":"鳥取家住宅東門","kana":"とっとりけじゅうたくひがしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県三豊市豊中町笠田笠岡字五右衛門1764-1","lat":34.15274167,"lng":133.70632778,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口1.4m、総延長4.3m","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"37 - 0460","desc":"主屋と新座敷の間の庭門で中庭を区画する。東門は腕木門で間口一・四メートル。袖塀と一連の切妻造桟瓦葺とし垂木を吹寄せに配す。門の西に控柱を立て、板戸を両開きに吊り込む。袖塀は土塀で腰を下見板張とし上部に筬欄間を入れる。丁寧な造作の門塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014105"},{"id":"00014101","register_sub_id":"101","register_pk":"508361","name":"鳥取家住宅比屋","kana":"とっとりけじゅうたくひや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県三豊市豊中町笠田笠岡字五右衛門1764","lat":34.15282778,"lng":133.70615,"geo_status":"db","era":"明治後期 ／平成22年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積37㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"37 - 0456","desc":"主屋の西、裏座敷の北に建つ離れで、当地で比屋と呼ぶ家族の若者用寝所である。二階建の切妻造桟瓦葺の東西棟で、北の軒下から下屋、西に濡縁を付す。外壁は真壁造中塗仕上、小屋組は登梁とする。内部は洋室に改修。住習慣の地方性を示す建物として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014101"},{"id":"00014097","register_sub_id":"101","register_pk":"508357","name":"鳥取家住宅風呂場棟","kana":"とっとりけじゅうたくふろばとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県三豊市豊中町笠田笠岡字五右衛門1764","lat":34.15268889,"lng":133.70624167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"37 - 0452","desc":"新座敷北西に建つ浴室棟。主屋と渡廊下で接続する。入母屋造桟瓦葺で妻飾を木連格子とする。縁の軒は角垂木に丸垂木を添えて二軒に造る。浴室は五右衛門風呂の周囲をタイルで飾り、折上天井に湯気抜きを設ける。三畳休息の間は凝った床構えで意匠が充実。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014097"},{"id":"00005923","register_sub_id":"101","register_pk":"106908","name":"富井家住宅主屋","kana":"とみいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県仲多度郡多度津町家中8-6","lat":34.27522997,"lng":133.7543221,"geo_status":"db","era":"文政11","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"37 － 0309","desc":"敷地の中央に位置し，南面して建つ。桁行６間半，梁間４間半規模，木造平屋建，切妻造，本瓦葺とする。四方に下屋を廻し，上部の外壁は漆喰塗とし，軒裏は垂木を波形に塗り込む。大きな改変がなく，当時の中級武士階級の住宅の形式及び外観を今日に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005923"},{"id":"00005924","register_sub_id":"101","register_pk":"106909","name":"富井家住宅新座敷","kana":"とみいけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県仲多度郡多度津町家中8-6","lat":34.27519286,"lng":133.75420934,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"37 － 0310","desc":"主屋の南西方に位置し，渡廊下で主屋と繋ぐ。桁行２間，梁間２間規模，木造平屋建，切妻造，本瓦葺とし，東側に奥行１間の下屋を張り出す。武士の住居施設であるが，門や塀で囲まずに，前面道路に近接させた建物配置は独特で，表構えを構成する建物として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005924"},{"id":"00005905","register_sub_id":"101","register_pk":"106890","name":"富井家住宅土蔵","kana":"とみいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県仲多度郡多度津町家中8-6","lat":34.27531145,"lng":133.75435524,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"37 － 0311","desc":"主屋の後方に南面して建ち，桁行２間，梁間２間，土蔵造２階建，切妻造，妻入，本瓦葺とする。出入口は引き戸で，上方に庇を設け，持送りは繰形で飾る。腰壁を海鼠壁とし，正面の壁出隅部分は軒下まで海鼠瓦貼を施す。意匠的に優れ，敷地内の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005905"},{"id":"00005759","register_sub_id":"101","register_pk":"106747","name":"富井家住宅門","kana":"とみいけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県仲多度郡多度津町家中8-6","lat":34.27514955,"lng":133.75428072,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.4m","structure_material":"木造","registered":"2006.10.18(平成18.10.18)","register_no":"37 － 0312","desc":"前面道路から後退して，主屋表口の前方に南面して建つ。控柱を設けた腕木門，切妻造，本瓦葺とする。東半は黒漆喰塗壁で，腰壁を押縁下見板で張り，西半を開き，格子戸と舞良戸の２枚を重ねて東半に引き込む。小規模ながら丁寧な造りで，敷地の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005759"},{"id":"00009076","register_sub_id":"101","register_pk":"162436","name":"長﨑家住宅表木戸及び板塀","kana":"ながさきけじゅうたくおもてきどおよびいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県東かがわ市引田字畑方2417-2他","lat":34.22483313,"lng":134.40513655,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造、瓦葺、塀延長9.6m","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"37 － 0376","desc":"主屋北側から本座敷東側に矩折れに延びる高塀で、延長9.6メートル、一文字瓦葺。東面中央に引違格子戸の表木戸を開き、瓦庇を付ける。塀は腰下見板張で、上部を漆喰塗りの真壁とし、開口に竹格子を組む。簡易ながら清楚な雰囲気で街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009076"},{"id":"00009073","register_sub_id":"101","register_pk":"162433","name":"長﨑家住宅本座敷","kana":"ながさきけじゅうたくおもてざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県東かがわ市引田字畑方2417-2他","lat":34.22475733,"lng":134.40499648,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"37 － 0373","desc":"主屋の西北に位置する。寄棟造桟瓦葺で、東妻面に入母屋造の玄関を張り出す。木造平屋建、建築面積78平方メートル。東西に八畳二室を並べ、南・西面を縁として下屋を廻らす。付書院の格狭間風欄間や小壁の松菱障子、室境の欄間などに繊細な意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009073"},{"id":"00009074","register_sub_id":"101","register_pk":"162434","name":"長﨑家住宅上便所","kana":"ながさきけじゅうたくかみのべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県東かがわ市引田字畑方2417-2他","lat":34.22468812,"lng":134.40495364,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"37 － 0374","desc":"本座敷の西に位置し、榑縁で繋がる。桁行7.0メートル梁間3.0メートル、南北棟の寄棟造桟瓦葺で、東面に庇をかけて榑縁を付設する。北から便所、脱衣所、風呂と三室並べ、中央の脱衣所にはトコや袋戸棚などを設ける。良質な接客空間の一部をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009074"},{"id":"00009072","register_sub_id":"101","register_pk":"162432","name":"長﨑家住宅主屋","kana":"ながさきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県東かがわ市引田字畑方2417-2他","lat":34.22472932,"lng":134.40510524,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積148㎡","structure_material":"木造平屋一部2階建","registered":"2011.10.28(平成23.10.28)","register_no":"37 － 0372","desc":"旧街道に東面して建つ。入母屋造本瓦葺の木造2階建を主棟とし、背面南寄りに寄棟造桟瓦葺の角屋を付設。南寄りに入口土間を設け、北側に座敷を配する。正面は1階に出格子を構え、二階は大壁で軒まで漆喰で塗り込める。窓まわりなど丁寧な鏝仕事が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009072"},{"id":"00009075","register_sub_id":"101","register_pk":"162435","name":"長﨑家住宅土蔵","kana":"ながさきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県東かがわ市引田字畑方2417-2他","lat":34.22465352,"lng":134.40479545,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積92㎡","structure_material":"土蔵造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"37 － 0375","desc":"上便所の西後方に位置する。東西棟の切妻造本瓦葺で、南面に下屋を付設する。桁行17メートルと細長い建物で、東の旧米蔵と西の旧麹蔵からなる。土蔵造平屋建で、外壁は漆喰仕上げとし、腰に下見板を張る。引田の醤油醸造の歴史を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009075"},{"id":"00009077","register_sub_id":"101","register_pk":"162437","name":"長﨑家住宅土塀","kana":"ながさきけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県東かがわ市引田字畑方2417-2他","lat":34.22462386,"lng":134.40504592,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土塀、瓦葺、延長18m","structure_material":"土塀","registered":"2011.10.28(平成23.10.28)","register_no":"37 － 0377","desc":"主屋炊事場の南側、小路沿いに東西に延びる塀。折曲がり延長18メートル。高さ2.2メートル。切石基礎上に建ち、モルタルで仕上げ、上部に一文字瓦を葺く。敷地正面の高塀に対して、生活の場の土塀はモルタル仕上げとするなど、位置により仕様を変えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009077"},{"id":"00005033","register_sub_id":"101","register_pk":"106023","name":"中村家住宅主屋","kana":"なかむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市屋島東町字池の内1703、1651-3、1652-1","lat":34.34202207,"lng":134.10967127,"geo_status":"db","era":"明治元／昭和初期増築","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積255㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"37 － 0279","desc":"屋島南麓，屋島神社参道の東方に位置する。入母屋造，もと茅葺の四周に桟瓦葺の下屋庇を廻したつくりで，桁行８間，梁行５間の平面規模を有し，東南部に玄関と洋風応接間を，西側に仏間等を増築する。玄関脇の格子窓に鍔を嵌め込むなど上質で凝った造作が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005033"},{"id":"00005035","register_sub_id":"101","register_pk":"106025","name":"中村家住宅庭門及び塀","kana":"なかむらけじゅうたくにわもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県高松市屋島東町字池の内1703、1651-3、1652-1","lat":34.34205429,"lng":134.10951093,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"庭門 木造、瓦葺、間口1.6m、塀 石造、瓦葺、延長91m","structure_material":"庭門 木造","registered":"2005.11.10(平成17.11.10)","register_no":"37 － 0281","desc":"主屋南面のもと式台玄関脇から南方に延び，前庭と奥庭を仕切る。塀は，延長約１０ｍ，下部は大石積，上部は立合垣とし，中央南寄りに庭門を開ける。庭門は，間口１．６ｍ，切妻造，軒先を銅板張とした一文字瓦葺で，柱や冠木等に奇木を用いた凝ったつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005035"},{"id":"00004427","register_sub_id":"101","register_pk":"105417","name":"福濱家住宅土蔵","kana":"ふくはまけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県丸亀市飯野町東二124","lat":34.26881966,"lng":133.83926638,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0218","desc":"土蔵は敷地後方にある。土蔵造２階建，東西棟の切妻造，平入で，南面に蔵前の庇を設け，本瓦葺とする。石積基礎上に建ち，漆喰塗の外壁は腰を縦板で覆い，西妻には庇付小窓を設けるが，東妻には漆喰彫刻を飾る。内部は１階半分を畳敷の独立した居室とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004427"},{"id":"00004426","register_sub_id":"101","register_pk":"105416","name":"福濱家住宅納屋","kana":"ふくはまけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県丸亀市飯野町東二124","lat":34.2686698,"lng":133.83954996,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0217","desc":"街路沿いに建つ木造平屋建，切妻造で，敷地側を正面として下屋庇を設け，屋根は本瓦葺とする。真壁造だが，街路側は縦板で覆う。内部は隅部を間仕切って牛小屋とし，また中梁上に竹簀の子を敷いて上部をつし２階風物置とする。近代農家の様相を示す附属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004426"},{"id":"00005371","register_sub_id":"101","register_pk":"106359","name":"間島家住宅主屋","kana":"まじまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県高松市牟礼町牟礼字浜2534-1","lat":34.34869559,"lng":134.12278793,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積174㎡、便所付","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0291","desc":"三角形敷地の中央に南面して建つ。寄棟造，茅葺（鉄板仮葺）の身舎四周に本瓦葺の下屋を廻した四方蓋造。平面規模は桁行１８ｍ，梁行９ｍ規模で，東方を土間，西方を床上部とし，南面中央に式台玄関を設け，棟東寄りに煙出しを上げる。讃岐地方民家の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005371"},{"id":"00005375","register_sub_id":"101","register_pk":"106363","name":"間島家住宅外塀","kana":"まじまけじゅうたくそとべい","category":"住宅","subcategory":"その他工作","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県高松市牟礼町牟礼字浜2534-1","lat":34.34862969,"lng":134.12303911,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土塀、瓦葺、延長120m","structure_material":"土塀","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0295","desc":"敷地を囲む瓦葺屋根付き土塀で，東辺と西辺は水路の石垣上に建ち上がる。西辺では土蔵と主屋雪隠，東辺では納屋，南辺では長屋門を挟み，西面に潜口２箇所，東辺中央及び東頂点部に脇門を開く。屋敷地の特徴をよく示し，三角屋敷として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005375"},{"id":"00005373","register_sub_id":"101","register_pk":"106361","name":"間島家住宅土蔵","kana":"まじまけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県高松市牟礼町牟礼字浜2534-1","lat":34.3488619,"lng":134.12270552,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0293","desc":"主屋の北方，屋敷地の西辺沿いにほぼ南北棟で建つ。切妻造，本瓦葺，平入の２階建土蔵で，東面に本瓦葺の庇を差し掛けて戸口を設け，西面と北面の高い位置に小窓を開ける。桁行９ｍ，梁間６ｍとやや規模の大きい道具蔵で，屋敷地の北頂点部の要となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005373"},{"id":"00005372","register_sub_id":"101","register_pk":"106360","name":"間島家住宅長屋門","kana":"まじまけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県高松市牟礼町牟礼字浜2534-1","lat":34.34853396,"lng":134.12282038,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積138㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0292","desc":"主屋の南方，屋敷地南辺の西寄りに東西棟で建つ。入母屋造，もと茅葺で，ほぼ中央に門口を開け，背面側には本瓦葺の下屋を差し掛ける。外部は腰を縦板張，上部を白漆喰塗とする。桁行２２．３ｍと長大な長屋門で，屋敷構えに欠くことのできない存在となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005372"},{"id":"00005374","register_sub_id":"101","register_pk":"106362","name":"間島家住宅庭門及び土塀","kana":"まじまけじゅうたくにわもんおよびどべい","category":"住宅","subcategory":"その他工作","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県高松市牟礼町牟礼字浜2534-1","lat":34.34859665,"lng":134.12280851,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"庭門 木造、瓦葺、間口1.4m、土塀 瓦葺、延長13m","structure_material":"庭門 木造","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0294","desc":"主屋南面式台玄関の西から発して南へ延び，中途で西に折れて長屋門北面に取り付く瓦葺屋根付き土塀。主屋玄関前の前庭と主屋座敷前の奥庭とを南北に区切る内塀で，主屋寄りに切妻造，本瓦葺，間口１．４ｍの庭門を開ける。屋敷地南部を構成する要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005374"},{"id":"00007695","register_sub_id":"101","register_pk":"108677","name":"増井家住宅主屋","kana":"ますいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市扇町1-58-2","lat":34.34615555,"lng":134.03695666,"geo_status":"db","era":"明治40／昭和23増築・昭和31改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積131㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"37 － 0323","desc":"通りに北面して建つ。間口７．０ｍの木造つし２階建。内部は東に通り土間を設け、西を床上とし、背面に奥座敷などの増築を設ける。切妻造本瓦葺で、下屋庇を設け、１階正面には出格子窓を付け、上部黒漆喰仕上げとし、虫籠窓を穿つ。高松城下の町家形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007695"},{"id":"00007696","register_sub_id":"101","register_pk":"108678","name":"増井家住宅書院","kana":"ますいけじゅうたくしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県高松市扇町1-58-2","lat":34.34615852,"lng":134.03700972,"geo_status":"db","era":"江戸末期／昭和31改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺一部金属板葺、建築面積166㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"37 － 0324","desc":"主屋の東に連続して建つ。間口１５ｍの町家建築で、切妻造本瓦葺とし、正面に下屋庇を付ける。主屋に接して北に八畳と南に十畳を並べ、南の庭園に面して低い切目縁を付ける。十畳にはトコや天袋、平書院を構え、欄間や襖で飾る。瀟洒な書院座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007696"},{"id":"00007697","register_sub_id":"101","register_pk":"108679","name":"増井家住宅茶室","kana":"ますいけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市扇町1-58-2","lat":34.34602704,"lng":134.03703906,"geo_status":"db","era":"明治45／昭和31増築改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積99㎡、中潜及び待合付","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"37 － 0325","desc":"書院の南に南北棟で建つ。切妻造桟瓦葺で庇を設け、南西に切妻造の雲門庵を付け、庭園に中潜や待合を配する。北から八畳、四畳、六畳水屋を並べ、部屋ごと襖や窓の意匠を違える。雲門庵は四畳で、西にトコを構え、網代や掛込天井を張る。風趣に富む数寄屋建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007697"},{"id":"00004028","register_sub_id":"101","register_pk":"105018","name":"松浦家住宅長屋門","kana":"まつうらけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県坂出市林田町3803","lat":34.33398725,"lng":133.88422552,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0193","desc":"庄屋宅の長屋門。桁行９間半梁間２間規模，入母屋造，本瓦葺で，石積基礎の上に建ち，正面中央右寄りに門口を開ける。外装は白漆喰塗とし，正面のみ腰を海鼠壁に仕上げ，軒先を波形に塗込める。敷地内で方位を変えて移築し，ギャラリー等として活用している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004028"},{"id":"00014415","register_sub_id":"101","register_pk":"511404","name":"松賀屋主屋","kana":"まつがやおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県三豊市仁尾町仁尾字北丁980","lat":34.20260833,"lng":133.64469167,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積190㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0466","desc":"仁尾塩田を開いた商家の店舗兼住宅。二階建、入母屋造本瓦葺。南に通した土間の西半を台所とする。床上は東と西に各三室を並べて縁を廻らせ、建物中心に置いた階段の周りに二階の和室を配す特異な平面である。造作の質高く、豪商の威風を示す近代和風邸宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014415"},{"id":"00014416","register_sub_id":"101","register_pk":"511405","name":"松賀屋玄関棟","kana":"まつがやげんかんとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県三豊市仁尾町仁尾字北丁980","lat":34.2026,"lng":133.64481667,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0467","desc":"塩田経営の商家の玄関棟。東側道路に面する入母屋造平入。正面下屋は戸口の北に出格子を飾り、つし二階は鼠漆喰塗で虫籠窓を開く。南の土間から中庭を経て主屋土間に至る。床上は取次から和室を経て主屋に至る。取次の北は茶室である。商家の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014416"},{"id":"00014417","register_sub_id":"101","register_pk":"511406","name":"松賀屋土蔵","kana":"まつがやどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県三豊市仁尾町仁尾字北丁980","lat":34.202525,"lng":133.64482778,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0468","desc":"塩田経営の商家の玄関棟南に続く二階建土蔵。切妻造本瓦葺置屋根で、外壁は街路側は鼠漆喰塗で腰竪板張、敷地内側は黒漆喰塗で腰を七宝繋の海鼠壁として意匠を凝らす。東妻一階の虫籠窓は持送り付銅板葺庇を付す。小屋組は曲りの強い地棟で登り梁を受ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014417"},{"id":"00009070","register_sub_id":"101","register_pk":"162430","name":"松村家住宅主屋","kana":"まつむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県東かがわ市引田字畑方2334","lat":34.22652352,"lng":134.40425548,"geo_status":"db","era":"昭和前期／昭和26年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積164㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"37 － 0370","desc":"旧街道東側に占める敷地の西端に位置する。東西棟の入母屋造桟瓦葺を主棟とし、東奥に台所棟などを張出す。建築面積１６４㎡。北面に玄関を構え、南面に本座敷と奥座敷を並べ、玄関脇に居間を配する。座敷飾りや欄間などに良質な意匠を示す和風住宅","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009070"},{"id":"00009071","register_sub_id":"101","register_pk":"162431","name":"松村家住宅門及び塀","kana":"まつむらけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県東かがわ市引田字畑方2334","lat":34.2265792,"lng":134.40421475,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、塀延長32m、勝手口付","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"37 － 0371","desc":"敷地西辺に建ち、北端で東に折れる桟瓦葺の高塀で、総延長３２ｍを測る。土台上に方柱をたて、腰に竪板を張り、上部を真壁とする。壁は北面は漆喰仕上げ、西面は色壁とする。西面北端には庇をかけ、出入口とする。趣のある佇まいが街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009071"},{"id":"00011574","register_sub_id":"101","register_pk":"210503","name":"真鍋家住宅主屋","kana":"まなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市林町字宮西58-1","lat":34.29576889,"lng":134.06365806,"geo_status":"db","era":"明治34年／昭和59年改修","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積399㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"37-0419","desc":"主屋は高松市南方の平野部に位置する敷地の中央に建つ平屋建で、桁行一四間半、梁間六間の規模。屋根は寄棟造本瓦葺。南面中央に式台玄関を設け、その東に内向諸室と土間を、西には座敷等を配し、西端には折上格天井の仏間を設ける。質の高い意匠の大規模住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011574"},{"id":"00011576","register_sub_id":"101","register_pk":null,"name":"真鍋家住宅茶室","kana":"まなべけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市林町字宮西58-1","lat":34.295625,"lng":134.06344306,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"37-0421","desc":"敷地の南西隅に建つ茶室。入母屋造桟瓦葺で、庇は銅板葺とする。西面は敷地外塀と連続する白漆喰大壁造。四畳半と二畳の茶室二室を矩折に配し、間を水屋でつなぐ。順次整備された敷地内建物の内最後に建てられたもので、近代上層農家の暮らしぶりを今日に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011576"},{"id":"00011577","register_sub_id":"101","register_pk":null,"name":"真鍋家住宅土蔵","kana":"まなべけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市林町字宮西58-1","lat":34.29582694,"lng":134.063985,"geo_status":"db","era":"明治38年","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積163㎡","structure_material":"土蔵造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"37-0422","desc":"敷地東端北半に建つ。土蔵造二階建、切妻造本瓦葺で、北半を桁行六間、梁間三間の道具蔵、南半を桁行五間、梁間二間の米蔵とし、西面全長に渡って下屋庇を設ける。小屋組は登梁形式。小作米等を収めた規模の大きな土蔵で、大規模農家の営みを今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011577"},{"id":"00011582","register_sub_id":"101","register_pk":"210511","name":"真鍋家住宅土塀","kana":"まなべけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市林町字宮西58-1","lat":34.29580194,"lng":134.063465,"geo_status":"db","era":"明治15年頃","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"土塀、瓦葺、延長44m","structure_material":"土塀","registered":"2017.05.02(平成29.05.02)","register_no":"37-0427","desc":"敷地西面を画す土塀。南端は茶室に北端部は矩折に離れに接する。水路脇の石垣の上に土塀を築き、棟は瓦葺とする。土塀部分は外部白漆喰塗、内部は荒壁仕上とするが、茶室脇は網代仕上として変化を持たせている。長い漆喰塗の外壁で、地域の景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011582"},{"id":"00011581","register_sub_id":"101","register_pk":"210510","name":"真鍋家住宅中門及び塀","kana":"まなべけじゅうたくなかもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市林町字宮西58-1","lat":34.29564111,"lng":134.06361694,"geo_status":"db","era":"明治41年","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"門 木造、瓦葺、間口1.7m 塀 木造、銅板葺、総延長11m","structure_material":"門 木造","registered":"2017.05.02(平成29.05.02)","register_no":"37-0426","desc":"主屋玄関脇と長屋門の間を結び、主屋前の内庭を画する。中門は切妻造本瓦葺、間口一・五メートルの薬医門で、材はケヤキ。塀は玄関側を上部黒漆喰塗で腰は幅広の板張とし、一間毎に格子窓を配す。内庭側は腰上下とも網代壁とする。意匠を凝らした門と塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011581"},{"id":"00011578","register_sub_id":"101","register_pk":"210507","name":"真鍋家住宅長屋門及び土塀","kana":"まなべけじゅうたくながやもんおよびどべい","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市林町字宮西58-1","lat":34.295591,"lng":134.06371,"geo_status":"db","era":"明治前期／明治15年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"長屋門 木造平屋建、瓦葺、建築面積110㎡ 土塀 瓦葺、延長17m","structure_material":"長屋門 木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"37-0423","desc":"敷地南面中央を画す長屋門とその西に続く土塀。長屋門は桁行一一間半、梁間二間半の規模で、入母屋造本瓦葺。中央に間口二・五メートルの両開大戸を設け、東に納屋二室、西に納屋と居室を配す。白漆喰の大壁に腰海鼠壁とする外観で、屋敷構えを象徴する建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011578"},{"id":"00011579","register_sub_id":"101","register_pk":"210508","name":"真鍋家住宅納屋及び土塀","kana":"まなべけじゅうたくなやおよびどべい","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市林町字宮西58-1","lat":34.29590806,"lng":134.06392,"geo_status":"db","era":"明治8年頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"納屋 木造平屋建、瓦葺、建築面積59㎡ 土塀 瓦葺、延長17m","structure_material":"納屋 木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"37-0424","desc":"敷地北端中ほどに建つ納屋。東に続く土塀と、西端に裏門が附属する。内部を三室とする、桁行六間半、梁間二間の木造平屋建、切妻造本瓦葺であるが、南面は桟瓦に変えられている。北面は水路脇の石垣を基礎とする。屋敷構えの一端を構成する建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011579"},{"id":"00011575","register_sub_id":"101","register_pk":null,"name":"真鍋家住宅離れ","kana":"まなべけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市林町字宮西58-1","lat":34.295935,"lng":134.06358806,"geo_status":"db","era":"明治8年／大正15年改修","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積97㎡","structure_material":"木造平屋一部2階建","registered":"2017.05.02(平成29.05.02)","register_no":"37-0420","desc":"主屋背面に渡り廊下を介して建つ。現主屋より古く、隠居屋として建てられたと思われる離れで、桁行六間梁間三間、切妻造本瓦葺で蔵座敷風の外観を見せるオヘヤと、桁行三間梁間二間寄棟造桟瓦葺の二階建部分からなる。内部造作も優れる離れである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011575"},{"id":"00011580","register_sub_id":"101","register_pk":"210509","name":"真鍋家住宅東門及び土塀","kana":"まなべけじゅうたくひがしもんおよびどべい","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市林町字宮西58-1","lat":34.295495,"lng":134.06390694,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"東門 木造平屋建、瓦葺、建築面積17㎡ 土塀 瓦葺、延長13m","structure_material":"東門 木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"37-0425","desc":"長屋門の東側を画す切妻造本瓦葺の門と土塀。間口一・九メートルの両開戸の西には三畳大板敷の男衆部屋を配し、東側は矩折総延長一三メートルの土塀を延ばし、敷地内側に屋根を差し掛けて納屋として用いる。近代の大規模農家の有り様を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011580"},{"id":"00014425","register_sub_id":"101","register_pk":"511414","name":"丸岡家住宅裏土塀","kana":"まるおかけじゅうたくうらどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県三豊市三野町下高瀬字乙井533-1","lat":34.20166944,"lng":133.70539444,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、総延長16m","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0476","desc":"旧下高瀬村の商家の塀で、敷地西辺から矩折れに北辺に延び、主屋と土蔵の間を塞いで敷地北西隅を形作る。切妻造本瓦葺で、西辺内側に葺き下ろして物置とし、北辺東端に木戸を備える。黒漆喰真壁で、外側腰をモルタル塗とする。商家敷地背面の実用的な土塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014425"},{"id":"00014423","register_sub_id":"101","register_pk":"511412","name":"丸岡家住宅表土塀","kana":"まるおかけじゅうたくおもてどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県三豊市三野町下高瀬字乙井533-1","lat":34.20187778,"lng":133.70564444,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造、瓦葺、総延長27m","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0474","desc":"旧下高瀬村中心部通りに沿う商家の土塀。屋敷東辺から北辺へ矩折れに延びて住居を囲う。基礎に粗い切石を並べ、土塀は表を漆喰仕上、裏を中塗仕上とし、屋根を桟瓦葺とする。北辺は一段高く切上げ、中央に潜り戸を設ける。屋敷構えと街路の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014423"},{"id":"00014422","register_sub_id":"101","register_pk":"511411","name":"丸岡家住宅表門","kana":"まるおかけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県三豊市三野町下高瀬字乙井533-1","lat":34.20180833,"lng":133.70572778,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造、瓦葺、間口1.7m","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0473","desc":"旧下高瀬村中心部の通りに開く商家の袖塀付薬医門。寄棟造桟瓦葺で軒先銅板葺とし、軒は扇垂木に木舞打で格天井を設け、門扉鏡板は欅の一枚板とする。袖塀は桟瓦葺で懸魚で飾り、黒漆喰壁で腰を石張風の洗出し仕上とする。隣接の洋風店舗と好対照の和風意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014422"},{"id":"00014418","register_sub_id":"101","register_pk":"511407","name":"丸岡家住宅主屋","kana":"まるおかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県三豊市三野町下高瀬字乙井533-1","lat":34.20172778,"lng":133.70555278,"geo_status":"db","era":"大正後期／昭和前期・同５２年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積70㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0469","desc":"旧下高瀬村中心部で呉服店等を営んだ家の主屋。入母屋造本瓦葺の二階建の住宅で、玄関棟背面に中庭を挟んで位置し、南西へ角屋を延ばし湯殿とする。１階は付書院を備えた仏間座敷、２階は縁と勾欄を備え開放的な座敷とする。屋敷構えの中核で帆立瓦を載せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014418"},{"id":"00014420","register_sub_id":"101","register_pk":"511409","name":"丸岡家住宅居室棟","kana":"まるおかけじゅうたくきょしつとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県三豊市三野町下高瀬字乙井533-2","lat":34.20164444,"lng":133.70565,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積67㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0471","desc":"旧下高瀬村中心部の呉服店の居住棟。洋風店舗の背面に接続し、商家裏玄関の役割も果たす実用的な住居。二階建入母屋造桟瓦葺、真壁造で各階に和室二室。妻面の狐格子、軒裏木舞打とし、座敷床構えの用材や建具框・桟の仕事も丁寧で華美にせず、外観も質実。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014420"},{"id":"00014419","register_sub_id":"101","register_pk":"511408","name":"丸岡家住宅玄関棟","kana":"まるおかけじゅうたくげんかんとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県三豊市三野町下高瀬字乙井533-1","lat":34.20177222,"lng":133.70565278,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積77㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0470","desc":"旧下高瀬村中心部の通り沿いに建つ商家主屋の玄関棟。入母屋造四方下屋で本瓦葺、真壁造平屋建で、千鳥破風を掲げた式台玄関を構え、表門と主屋の間に位置する。全体に数寄屋風意匠で、控えの間、玄関間、書院付八畳座敷から成り、精緻な前彫床柱が出色。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014419"},{"id":"00014421","register_sub_id":"101","register_pk":"511410","name":"丸岡家住宅土蔵","kana":"まるおかけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県三豊市三野町下高瀬字乙井533-2","lat":34.201575,"lng":133.70551111,"geo_status":"db","era":"明治36年／昭和１２年改修","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0472","desc":"呉服店の敷地背面側西寄りに所在する土蔵。土蔵造二階建で腰海鼠壁、切妻造妻入本瓦葺起り屋根で鉢巻付。各階１室で１階は土間、２階は板敷で、屋根裏は割竹土居葺で素朴な造り。外周は木瓜型窓枠塗籠、繰形付庇持送り、鏝絵妻飾りなど豊富に装飾施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014421"},{"id":"00014424","register_sub_id":"101","register_pk":"511413","name":"丸岡家住宅南土塀","kana":"まるおかけじゅうたくみなみどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県三豊市三野町下高瀬字乙井533-2","lat":34.20155833,"lng":133.70560833,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、総延長21m","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0475","desc":"旧下高瀬村の商家の塀で、敷地側面の南辺から西へ矩折れに延びて土蔵に取り付く。延べ石基礎とし、黒漆喰真壁に腰を洗い出し仕上として背面に控え石柱を付し、桟瓦葺屋根を腕木で支える。矩折れ部分に街路側と裏庭側に潜り戸を設ける。街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014424"},{"id":"00005365","register_sub_id":"101","register_pk":"106353","name":"宮武家住宅（江戸そば日月庵）主屋","kana":"みやたけけじゅうたく（えどそばにちげつあん）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県丸亀市飯山町上法軍寺字岡1528-1他","lat":34.24363786,"lng":133.8595818,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積263㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0298","desc":"明治２９年創業の造り酒屋の主屋。東西棟，入母屋造，桟瓦葺の木造２階建で，四周に下屋を廻し，平面規模を桁行１８．２ｍ，梁行１０．５ｍとする。東方を土間，南面中央を式台玄関とし，北東に釜屋，西南に湯殿を付ける。国道沿い近くに位置し目印となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005365"},{"id":"00003321","register_sub_id":"101","register_pk":"104311","name":"村尾家住宅石垣","kana":"むらおけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市西植田町字清定3186","lat":34.24038426,"lng":134.07417509,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"石造、延長35m","structure_material":"石造","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0148","desc":"屋敷南の前庭に築かれた長さ約３５ｍ，高さ約２ｍの石垣。頂部を葛石で見切った谷積風で，中央東寄りには瓢箪型や扇型の飾り石を精緻に組む。東側は地形なりに勾配がつき，西側は一段下がって鍵型に折る。長屋門とともに屋敷正面の景観を豪壮に仕上げている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003321"},{"id":"00003320","register_sub_id":"101","register_pk":"104310","name":"村尾家住宅北土蔵","kana":"むらおけじゅうたくきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市西植田町字清定3186","lat":34.24086133,"lng":134.0741364,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0147","desc":"主屋の北側に建つ。土蔵造・２階建，東西棟の切妻造・本瓦葺，外壁は漆喰塗を目板張で覆っている。東西両面の２階に格子窓を設ける。地棟の両端は妻壁に出し，漆喰で木口を保護するが，西面は扇形に「違扇」風の鏝絵で飾るなど，丁寧な仕事が伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003320"},{"id":"00003316","register_sub_id":"101","register_pk":"104306","name":"村尾家住宅主屋","kana":"むらおけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県高松市西植田町字清定3186","lat":34.240746,"lng":134.074127,"geo_status":"db","era":"天保13","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"木造平屋建、鉄板葺及び瓦葺、建築面積204㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0143","desc":"敷地奥に南面して建ち，小屋内の部材墨書から天保１３年上棟と判明する。寄棟造・鉄板葺で，四周に瓦葺の下屋を廻したいわゆる四方蓋造で，側廻りは改修されたが，軸部等はよく残る。桁行約２１ｍと規模も雄大で，山裾に屋敷を構えた旧家の中心的存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003316"},{"id":"00003317","register_sub_id":"101","register_pk":"104307","name":"村尾家住宅長屋門","kana":"むらおけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市西植田町字清定3186","lat":34.240471,"lng":134.074158,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積115㎡、土塀延長30m付","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0144","desc":"主屋の南側にある。桁行約２１ｍと長大で，木造・平屋建，東西棟の入母屋造・本瓦葺，東面に寄棟造の納屋等を付属する。門口は西寄に構え，東を２室，西を１室とし，外壁は漆喰塗で，腰を海鼠壁とする。豪壮かつ重厚なつくりで，景観上も際だった存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003317"},{"id":"00003319","register_sub_id":"101","register_pk":"104309","name":"村尾家住宅納屋","kana":"むらおけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市西植田町字清定3186","lat":34.240662,"lng":134.07433427,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0146","desc":"主屋東南，南土蔵の北に連続して建つ。木造・平屋建，南北棟の切妻造・桟瓦葺で，西面に大きな開口部を設ける。外壁は真壁造であるが，東面は縦板張で覆う。大規模な農家に欠かせない施設であるとともに，東辺の石垣上にあって，屋敷の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003319"},{"id":"00003318","register_sub_id":"101","register_pk":"104308","name":"村尾家住宅南土蔵","kana":"むらおけじゅうたくみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市西植田町字清定3186","lat":34.240547,"lng":134.0742968,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積68㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0145","desc":"もとは米蔵で，主屋の東南に建つ。土蔵造・２階建，置屋根式で南北棟の切妻造・本瓦葺，外壁は漆喰塗とする。西面に２カ所の戸口を設け，庇をつける。全体に丁寧なつくりで，南面の縦格子窓，東面の小さな丸窓など，各部の意匠にも細かい配慮がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003318"},{"id":"00004034","register_sub_id":"101","register_pk":"105024","name":"元屋商店保齢亭","kana":"もとやしょうてんほれいてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡土庄町字井ノ奥甲762-2","lat":34.48389781,"lng":134.18186178,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積4.9㎡、石造水槽付属","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0199","desc":"醸造場南西方丘陵地の別宅に建つ。方１間，宝形造，桟瓦葺の茶室で，外装は縦板張とし，上部黒土塗壁との見切りの押縁は円弧を描く。西側に付属する長辺３ｍ短辺１．５ｍ規模の花崗岩による石造水槽は水に乏しい島の水事情を物語る遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004034"},{"id":"00014212","register_sub_id":"101","register_pk":"508842","name":"森家住宅長屋門","kana":"もりけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市香川町川東下字中村595他","lat":34.23935556,"lng":134.03144167,"geo_status":"db","era":"明治40年／昭和2年移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"37-0463","desc":"敷地南端の通りに南面して建つ長屋門。平屋建、入母屋造桟瓦葺、中央に板戸両開きの門扉、東脇に潜り戸を付し、東西を納屋とする。南面は大壁造黒漆喰塗で腰は簓子下見板張とし、当初の姿をよく留める。精米精麦等で栄えた当家の家格や歴史を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014212"},{"id":"00014211","register_sub_id":"101","register_pk":"508841","name":"森家住宅納屋","kana":"もりけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市香川町川東下字中村593-2","lat":34.239525,"lng":134.03160556,"geo_status":"db","era":"明治40年頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造一部2階建、瓦葺、建築面積99㎡","structure_material":"木造一部2階建","registered":"2022.02.17(令和4.02.17)","register_no":"37-0462","desc":"讃岐平野香東川沿い集落の農家の納屋。敷地東端に西面して建つ南北棟。土蔵造で軒先まで漆喰で塗込め、一部二階建切妻造桟瓦葺、西面に庇を付し、北と東面の腰は竪板張。内部は南北二室で北を板敷とする。精米精麦等で栄えた旧家の風格ある屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014211"},{"id":"00004035","register_sub_id":"101","register_pk":"105025","name":"山口家住宅主屋","kana":"やまぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県小豆郡土庄町大部字仲ノ坪甲1940","lat":34.54621826,"lng":134.27987619,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積129㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0200","desc":"大部を二分する桂川の西方集落に位置する。４周に下屋を廻した入母屋造，桟瓦葺の平屋建で，東方を下手として玄関土間を設け，北に湯殿・厠を張出し，東には物置を添わせる。腰を縦板張，上部を真壁造とした端正なつくりの和風住宅建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004035"},{"id":"00003624","register_sub_id":"101","register_pk":"104614","name":"ヤマサン醤油洋館","kana":"やまさんしょうゆようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47645131,"lng":134.32033997,"geo_status":"db","era":"昭和初期／昭和34移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0181","desc":"ボイラー室の南方，操作場の西方に東西棟で建つ。桁行４．４ｍ梁間３．２ｍの平屋建１室洋館で，屋根は袴腰形の半切妻造とし，スパニッシュの洋瓦を葺く。小規模ながら，縦長の窓やたちの高いプロモーションなど洋風建築の要素を有する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003624"},{"id":"00004657","register_sub_id":"101","register_pk":"105647","name":"やます坂下家住宅主屋","kana":"やますさかしたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字坂ノ山甲291-2","lat":34.47599388,"lng":134.32258131,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積131㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0249","desc":"山裾傾斜地に石垣擁壁で造成した住宅屋敷地のほぼ中央に南面して建つ。桁行１３ｍ梁間９ｍ規模，切妻造，桟瓦葺の木造平屋建で，四周に下屋を廻す。外部は真壁造で，壁は黒漆喰で仕上げる。玄関回りの庇支柱に曲材を用いるなど随所に凝ったつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004657"},{"id":"00004658","register_sub_id":"101","register_pk":"105648","name":"やます坂下家住宅長屋門","kana":"やますさかしたけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字坂ノ山甲291-2","lat":34.47600722,"lng":134.32274639,"geo_status":"db","era":"明治41／大正中期増築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積111㎡、石垣延長30m付","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0250","desc":"主屋の東方に南北棟で建つ。桁行１４ｍ規模，切妻造，桟瓦葺の木造平屋建で，東西両側面に下屋を差し掛け，西面南端に東西棟，切妻造の木造平屋建を増築し，西面軒下小壁と増築部西妻面に円形小窓を開ける。東面下屋内に門口開けるアプローチは特異な構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004658"},{"id":"00004659","register_sub_id":"101","register_pk":"105649","name":"やます坂下家住宅洋館","kana":"やますさかしたけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字坂ノ山甲291-2","lat":34.47599682,"lng":134.32251695,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積27㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0251","desc":"主屋の西に接して東西棟で建つ。桁行４ｍ梁間６ｍ規模の木造２階建洋館で，急傾斜の切妻屋根と緑色のフランス瓦に特徴。外部はモルタル塗，内部は建具や天井中心飾りなど洋風意匠でまとめる。たちの高い形姿は一際目立ち，地域のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004659"},{"id":"00002460","register_sub_id":"101","register_pk":"103450","name":"山田家（旧清酒源氏正宗醸造元）長屋門","kana":"やまだけ（きゅうせいしゅげんじまさむねじょうぞうもと）ながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県高松市牟礼町牟礼3186","lat":34.35310408,"lng":134.12968808,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積158㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0076","desc":"八栗寺参道から北へ入ったアプローチ道路の突き当たりに主屋を背にして建つ。主屋と同様桁行１４間規模の長大な入母屋造，本瓦葺の長屋門で，主屋の式台玄関と土間玄関に対応した位置に門を開ける。近年改装され食事室としても利活用が図られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002460"},{"id":"00002465","register_sub_id":"101","register_pk":"103455","name":"山田家（旧清酒源氏正宗醸造元）庭門","kana":"やまだけ（きゅうせいしゅげんじまさむねじょうぞうもと）にわもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県高松市牟礼町牟礼3186","lat":34.35314124,"lng":134.12948309,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、間口1.1m、石造塀付","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0081","desc":"主屋西南部の客間近くに建ち，南庭と西側の庭とを仕切る役目を果たす。間口半間ほどの簡素な腕木門で，左右に低い石積塀を従え，見付幅３１ｃｍの弓形の大型瓦で葺いている点に特徴があり，主屋・長屋門・酒蔵で囲われた庭園の西方の点景となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002465"},{"id":"00004037","register_sub_id":"101","register_pk":"105027","name":"やまひら醤油隠居屋","kana":"やまひらしょうゆいんきょや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡土庄町大部字浜庄甲3260","lat":34.54552932,"lng":134.28359661,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0202","desc":"小路に沿った敷地西辺の中程に位置し，東西棟で建つ。入母屋造，桟瓦葺の木造２階建で，石積基礎の上に建ち，桁行３間半梁行２間半の平面規模を有する。２階西北の出隅部に矩折の手摺付肘掛窓を廻すなど小路側に離れ風の開放的な構えをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004037"},{"id":"00004038","register_sub_id":"101","register_pk":"105028","name":"やまひら醤油土蔵","kana":"やまひらしょうゆどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県小豆郡土庄町大部字浜庄甲3260","lat":34.54547627,"lng":134.28358669,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0203","desc":"隠居屋の南方に位置し，敷地西辺沿いの小路に屋号を印した西妻面を見せて東西棟で建つ。桁行４間梁間２間半規模，切妻造，本瓦葺の２階建土蔵で，北桁行全面に庇を差し掛け，東寄りに戸口を開ける。湾曲した庇持送りにも特徴がある。敷地西辺沿いの構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004038"},{"id":"00004660","register_sub_id":"101","register_pk":"105650","name":"山吉山本家住宅主屋","kana":"やまよしやまもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町馬木字今坂甲710","lat":34.47516534,"lng":134.32477197,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積233㎡、渡り廊下付","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0252","desc":"敷地中央東寄りに東西棟で建つ。桟瓦葺，切妻造の四周に本瓦葺の下屋を廻した木造平屋建で，桁行１８ｍ梁行１１ｍの平面規模。東方を土間，西方を床上部とし，南面のほぼ中央に入母屋造玄関を張り出し，北東に切妻造の釜屋を突き出すなど豪壮な構えをとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004660"},{"id":"00004663","register_sub_id":"101","register_pk":"105653","name":"山吉山本家住宅土蔵","kana":"やまよしやまもとけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町馬木字今坂甲710","lat":34.47526362,"lng":134.32455328,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0255","desc":"離れ屋の北方，便所の北面に接して建つ。桁行２間半梁間２間，南北棟，切妻造，桟瓦葺，平入の２階建土蔵で，東面北寄りに庇を設けて戸口を開け，外部は腰縦板張，上部白漆喰塗に仕上げる。開口部の少ない閉鎖的なつくりの道具蔵で，屋敷構えの一要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004663"},{"id":"00004665","register_sub_id":"101","register_pk":"105655","name":"山吉山本家住宅練塀","kana":"やまよしやまもとけじゅうたくねりべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町馬木字今坂甲710","lat":34.47507436,"lng":134.32443045,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石練塀、瓦葺、折曲り延長30m","structure_material":"石練塀","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0257","desc":"番屋西妻面から西方に向かい，屋敷地西南隅で北に折れ，諸味蔵手前で東に矩折れて離れ屋西北端に取り付く。花崗石の精緻な切石積の石垣擁壁上に築かれ，石垣の切石より小振りな割石を用いて高さ１．２ｍに巧みに積み上げ，頂部に桟瓦葺の小屋根を載せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004665"},{"id":"00004662","register_sub_id":"101","register_pk":"105652","name":"山吉山本家住宅離れ屋","kana":"やまよしやまもとけじゅうたくはなれや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町馬木字今坂甲710","lat":34.4751709,"lng":134.32451607,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0254","desc":"主屋の西方に東西棟で建ち，主屋とは渡り廊下で結ばれる。入母屋造，本瓦葺の木造平屋建で，四周に桟瓦葺の下屋を廻し，平面規模は桁行１４ｍ梁行６ｍとする。隠居屋と伝え，南面東寄りに式台玄関を設け，北方に青色装飾タイル敷の便所を付属する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004662"},{"id":"00004661","register_sub_id":"101","register_pk":"105651","name":"山吉山本家住宅番屋","kana":"やまよしやまもとけじゅうたくばんや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町馬木字今坂甲710","lat":34.4750489,"lng":134.3246429,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡、庭門付","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0253","desc":"主屋の南方に東西棟で建つ長屋門。桁行９ｍ規模，入母屋造，本瓦葺の木造平屋建で，東端に門口を開く。南北両面に庇を差し掛け，壁は黒漆喰塗に仕上げる。東面は，腰縦板張，上部黒漆喰塗とし，境に水切瓦を付ける。屋敷地の構えに欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004661"},{"id":"00003627","register_sub_id":"101","register_pk":"104617","name":"ヤマロク醤油石練塀","kana":"やまろくしょうゆいしねりべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町安田字空条甲1607","lat":34.48631915,"lng":134.32066187,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"石造、瓦葺、延長8m","structure_material":"石造","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0184","desc":"屋敷地西南隅部に位置し，北端は醸造主住宅主屋に取り付く。地元産の黒石を使用し，粘土目地で矢筈積に積み，瓦葺の小屋根を架ける。安田大川の氾濫に備えた施設であるが，当地域の屋敷構えに独特の風情を醸し出す要素にもなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003627"},{"id":"00004649","register_sub_id":"101","register_pk":"105639","name":"島一照下家住宅米蔵","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字中筋甲1506-5","lat":34.46853052,"lng":134.32332038,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0241","desc":"主屋の東南方に位置し，南北棟で建つ。桁行３間梁間２間規模，切妻造，本瓦葺の２階建土蔵で，外部は腰焼杉縦板張，上部白漆喰塗とし，軒に鉢巻を廻す。西面に戸口と高窓を開けただけの閉鎖的なつくりで，主屋玄関に至る通路景観に欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004649"},{"id":"00004647","register_sub_id":"101","register_pk":"105637","name":"島一照下家住宅離れ屋","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字中筋甲1506-1","lat":34.46868817,"lng":134.32302252,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積49㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0239","desc":"隠居所として建設と伝え，主屋の西に接して南北棟で建つ。桁行４間半梁行３間規模，寄棟造，桟瓦葺の木造総２階建で，南妻面に上下階とも開口をとり，外部は白漆喰塗の上部小壁を除いて縦板張とする。乾蔵，通用口塀とともに敷地西辺の景観を整える構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004647"},{"id":"00004646","register_sub_id":"101","register_pk":"105636","name":"島一照下家住宅主屋","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字中筋甲1506-1","lat":34.46870166,"lng":134.32315259,"geo_status":"db","era":"大正13／昭和22増築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積197㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0238","desc":"敷地北寄りに位置し，東西棟で建つ。主体部はわずかに起りを付けた入母屋造，本瓦葺で，四周に本瓦葺の下屋を廻し，東面に入母屋造，本瓦葺の玄関を突出させる。桁行１８ｍと規模も大きく，豪壮な正面の構えは醤油醸造業の隆盛を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004646"},{"id":"00004648","register_sub_id":"101","register_pk":"105638","name":"島一照下家住宅乾蔵","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字中筋甲1506-1","lat":34.46874766,"lng":134.32304876,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡、袖塀付","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0240","desc":"主屋の西方，離れ屋の北方に位置し，道路に北西角隅面を見せて東西棟で建つ。桁行２間半梁間２間規模，切妻造，本瓦葺，妻入の２階建道具蔵で，腰縦板張，上部白漆喰塗とし，軒鉢巻を黒漆喰で仕上げる。高窓庇の持ち送りに漆喰装飾を施すなど丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004648"},{"id":"00002843","register_sub_id":"101","register_pk":"103833","name":"宝食品天川亭（旧天川家住宅土蔵）","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町草壁本町615-25","lat":34.47840864,"lng":134.29973066,"geo_status":"db","era":"昭和10頃／平成5移築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵2階建、瓦葺、建築面積25㎡","structure_material":"土蔵2階建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0111","desc":"内海町苗羽芦の浦地区所在の土蔵を草壁港近くに移築。福井亭の南方に並び建つ。豊島石による基礎，本瓦葺，切妻造，平入と福井亭と同様なつくりで，規模は桁行６ｍとひとまわり大きく，たちもやや高い。２棟一体となり地区の集会施設として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002843"},{"id":"00009399","register_sub_id":"101","register_pk":"194192","name":"井谷家住宅石垣及び土塀","kana":"いたにけじゅうたくいしがきおよびどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県北宇和郡鬼北町大字下鍵山376-1","lat":33.33532279,"lng":132.79766979,"geo_status":"db","era":"明治26年頃","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"石垣 石造、総延長44m 土塀 土塀、瓦葺、総延長26m","structure_material":"石垣 石造","registered":"2012.08.13(平成24.08.13)","register_no":"38 － 0105","desc":"主屋玄関正面に設けられた石段の東西にのびる石垣と塀である。石垣は自然石を高さ約一メートルに野面積とし、総延長四四メートルを測る。石垣上に築いた土塀は総延長二六メートル高さ約〇・八メートル、切妻造桟瓦葺である。屋敷地の表構えに風格を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009399"},{"id":"00009401","register_sub_id":"101","register_pk":"194194","name":"井谷家住宅給水用隧道","kana":"いたにけじゅうたくきゅうすいようずいどう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県北宇和郡鬼北町大字下鍵山955","lat":33.33545323,"lng":132.79775515,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"石造、幅員0.9m、奥行22m","structure_material":"石造","registered":"2012.08.13(平成24.08.13)","register_no":"38 － 0107","desc":"主屋東端背後の裏山に穿たれた給水用の隧道である。半円アーチの入口を高さ二・四メートル幅二・三メートルに切石積で築き、両側に袖を設ける。内部は素堀りで、奥行は二一・八メートルを測り、最奥部の湧水を使用する。独特な形式をもつ取水施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009401"},{"id":"00009398","register_sub_id":"101","register_pk":"194191","name":"井谷家住宅蔵","kana":"いたにけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県北宇和郡鬼北町大字下鍵山376-1","lat":33.33537042,"lng":132.79752377,"geo_status":"db","era":"明治26年頃","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"38 － 0104","desc":"主屋西側に廊下を介して建ち、土蔵造二階建、桁行一〇・一メートル梁間五メートル、切妻造置屋根式の桟瓦葺である。花崗岩積みの礎石上に建ち、外壁は焼スギ板を竪板張とし、各面に穿つ窓廻りは漆喰塗で仕上げる。旧家の屋敷構えを構成する土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009398"},{"id":"00009397","register_sub_id":"101","register_pk":"194190","name":"井谷家住宅主屋","kana":"いたにけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県北宇和郡鬼北町大字下鍵山376-1","lat":33.33539898,"lng":132.79773078,"geo_status":"db","era":"明治26年頃","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積236㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"38 － 0103","desc":"山裾の敷地に南面して建つ。木造平屋建、建築面積二三六平方メートル、切妻造桟瓦葺で、正面に切妻造の玄関を構える。玄関の東西前列に丁寧なつくりの客間や主人室、隠居部屋を並べ、後列に台所など内向きの部屋を配する。当地の近代化の一端を示す和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009397"},{"id":"00009400","register_sub_id":"101","register_pk":"194193","name":"井谷家住宅南面石垣","kana":"いたにけじゅうたくなんめんいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県北宇和郡鬼北町大字下鍵山375他","lat":33.3352031,"lng":132.79773141,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造、総延長100m","structure_material":"石造","registered":"2012.08.13(平成24.08.13)","register_no":"38 － 0106","desc":"敷地南辺西寄りの斜路の東西に築かれた石垣である。砂岩系の石を用いて、野面積などで積み上げ、最大高さ約二・七メートル、長さは東側に折曲がり七三・七メートル、西側に同じく二六・二メートルを測る。山間部の旧家の屋敷らしい構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009400"},{"id":"00003333","register_sub_id":"101","register_pk":"104323","name":"井村家住宅主屋","kana":"いむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県南宇和郡愛南町小山153","lat":32.95892857,"lng":132.66073448,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積143㎡","structure_material":"木造平屋一部2階建","registered":"2003.03.18(平成15.03.18)","register_no":"38 － 0042","desc":"市街地東の山あいにあり，南を正面とする。木造・一部２階建で，中央玄関を境に，平屋建で下屋を廻した西半は座敷等を伝統的な和風でまとめ，１階に応接間や食堂を配した東半は縦長窓や緑色の屋根瓦などに洋風意匠が伺える。地方における和洋折衷住宅の事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003333"},{"id":"00005774","register_sub_id":"101","register_pk":"106762","name":"上田家石垣","kana":"うえだけいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県喜多郡内子町袋口3768","lat":33.61332198,"lng":132.63616376,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、延長31m","structure_material":"石造","registered":"2006.10.18(平成18.10.18)","register_no":"38 － 0072","desc":"傾斜地にある敷地の南東辺に位置する。長さは天端２８ｍ，下端３１ｍで，高さを６ｍとし，細長に割った青石を末広状に空積とする。また，見付面に７つの大きな青石を並べて埋め込む点は独特で，地域の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005774"},{"id":"00004053","register_sub_id":"101","register_pk":"105043","name":"梅美人酒造住宅主屋","kana":"うめびじんしゅぞうじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県八幡浜市1557-2","lat":33.46519288,"lng":132.42577422,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"38 － 0054","desc":"事務所の西南方に位置し，南側に桁行２間半梁行４間，南北棟，切妻造，桟瓦葺，木造２階建の座敷棟を配し，北東端の食堂が事務所背面南寄りに取り付く。座敷棟の南妻面はモルタル塗，目地切仕上げとして石造風に見せて敷地南辺沿いの街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004053"},{"id":"00002693","register_sub_id":"101","register_pk":"103683","name":"大野家住宅長屋門","kana":"おおのけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県大洲市菅田町宇津甲807","lat":33.501221,"lng":132.621643,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積218㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"38 － 0019","desc":"市東部，肱川そばの山際に建つ。野面積石垣の上に南面し，西を切妻造，東を入母屋造，中央部に越屋根を設ける。桁行３０ｍ強の大規模な長屋門で，真壁に平・出格子窓を巧みに配し変化のある外観をつくる。高台にあり地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002693"},{"id":"00004094","register_sub_id":"101","register_pk":"105084","name":"越智家住宅数寄屋","kana":"おちけじゅうたくすきや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県西条市壬生川32-1","lat":33.93669114,"lng":133.08662456,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積248㎡","structure_material":"木造平屋一部2階建","registered":"2002.02.14(平成14.02.14)","register_no":"38 － 0021","desc":"南北に細長い敷地の南側にある。切妻と入母屋が混在し，真壁，簓子下見，立板張と変化のある外観を呈す。内部には，銘木を要所に配し，折上格子・網代天井や欄間に幾何学的な意匠を凝らす。全体として質の高い数寄屋を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004094"},{"id":"00002695","register_sub_id":"101","register_pk":"103685","name":"越智家住宅茶室","kana":"おちけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県西条市壬生川32-1","lat":33.93685582,"lng":133.08647083,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"38 － 0022","desc":"主屋と数寄屋に挟まれた敷地中央部にある。３畳台目向う切りで躙口を設けた本格的な茶室。床柱を中柱に見立てた巧みな造りと，変化のある棚の造作，精妙に配された開口部の格子など，全体に意趣に富んだ造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002695"},{"id":"00002694","register_sub_id":"101","register_pk":"103684","name":"越智家住宅店舗及び居宅","kana":"おちけじゅうたくてんぽおよびきょたく","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県西条市壬生川35-1","lat":33.93696607,"lng":133.08628317,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積346㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"38 － 0020","desc":"市中心部の幹線道路沿いの敷地に北面して建つ。表屋造風のつくりで，表側店舗をたちが高い下屋庇付の切妻造２階建，奥の住居部を平屋建とする。全体に本瓦を葺き，破風を漆喰塗，側壁を縦板張とする。伊予地方を代表する商家で街路景観形成に欠かせない要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002694"},{"id":"00012841","register_sub_id":"101","register_pk":"367744","name":"上弓削田坂家住宅主屋","kana":"かみゆげたさかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県越智郡上島町弓削上弓削313","lat":34.27561111,"lng":133.21086389,"geo_status":"db","era":"大正6年／平成30年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"38 － 130","desc":"弓削島西岸の港町にある住宅。主屋は敷地中央に北面して建つ。入母屋造桟瓦葺のつし二階建で正背面に下屋を付し、背面西端に台所を角屋で出す。西に土間、東に2列4室を配し、東列表を座敷とする。瀬戸内海島嶼部の民家建築の形式を継承した近代の和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012841"},{"id":"00012842","register_sub_id":"101","register_pk":"367745","name":"上弓削田坂家住宅土蔵","kana":"かみゆげたさかけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県越智郡上島町弓削上弓削313","lat":34.27558889,"lng":133.21078889,"geo_status":"db","era":"大正6年頃／昭和前期・平成26年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"38 － 131","desc":"主屋背面の角屋に接続して建つ。土蔵造二階建、切妻造桟瓦葺で、北東二面に戸口を設けて吹放しの下屋を廻す。外壁は縦板張とし、二階東面に庇付の窓を設ける。内部に改変があるが外観は旧状をよく留め、瀬戸内海島嶼部の伝統的な町家の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012842"},{"id":"00012843","register_sub_id":"101","register_pk":"367746","name":"上弓削田坂家住宅門及び塀","kana":"かみゆげたさかけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県越智郡上島町弓削上弓削313","lat":34.27568889,"lng":133.21089722,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"門 木造、瓦葺、間口2.4m 塀 木造、瓦葺、総延長14m","structure_material":"門 木造","registered":"2019.03.29(平成31.03.29)","register_no":"38 － 132","desc":"敷地北面中央に開く門と左右に連なる塀。門は間口2・4メートル奥行1・2メートル、切妻造桟瓦葺で左右袖壁付の門扉を設ける。塀は前庭をコの字形に区切る土塀で、外側は縦板張、屋根は桟瓦葺である。主屋とともに港町の街路の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012843"},{"id":"00012837","register_sub_id":"101","register_pk":"367740","name":"木村家住宅主屋","kana":"きむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県松山市三津一丁目63他","lat":33.86547194,"lng":132.71321389,"geo_status":"db","era":"明治14年","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"38 － 126","desc":"港沿いの裏通りに西面して建つ間口四間半の町家。上下階とも正面に出格子を入れ、建ちの高い二階は出桁造で、貫をみせた真壁造漆喰塗とする。内部は南を広い土間とし、北にミセと座敷二室を一列に並べ、二階に広間を設ける。明治期の港町の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012837"},{"id":"00012839","register_sub_id":"101","register_pk":"367742","name":"木村家住宅土蔵","kana":"きむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県松山市三津一丁目63他","lat":33.86547194,"lng":132.71321389,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、金属板葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"38 － 128","desc":"敷地東面の過半を占めて建つ。土蔵造二階建、切妻造鉄板葺で、西面南寄りに戸口を設け、一部腰を海鼠壁とする。港沿いの通りに面する東面は一階に三連の上下窓、二階中央に縁取付の窓を設け、腰を縦板張とする。離れと同じく港側の屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012839"},{"id":"00012838","register_sub_id":"101","register_pk":"367741","name":"木村家住宅離れ","kana":"きむらけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県松山市三津一丁目63他","lat":33.86547194,"lng":132.71321389,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、金属鈑葺、建築面積21㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"38 － 127","desc":"敷地の東北隅、土蔵北面に接して建つ。切妻造鉄板葺の二階建で、西面北端を渡廊下で主屋と接続する。一階は北を廊下、南を倉庫とし、東面北端に出入口を設ける。二階の座敷は海を望む東面全面を手摺付の窓とする。土蔵と並んで港側の屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012838"},{"id":"00012840","register_sub_id":"101","register_pk":"367743","name":"木村家住宅風呂","kana":"きむらけじゅうたくふろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県松山市三津一丁目63他","lat":33.86547194,"lng":132.71321389,"geo_status":"db","era":"明治14年頃／大正3年改修","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積6.2㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"38 － 129","desc":"敷地南面の中央部、主屋と土蔵の間に建つ。片流れ屋根鋼板葺で、出桁で軒を深くつくり、主屋と土蔵をつなぐ通路を兼ねる。もと物置で、後に東半を風呂、西半を釜場に改修した。風呂の内壁を装飾タイル張とするなど、大正期の地域名士の暮らしの一端を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012840"},{"id":"00006253","register_sub_id":"101","register_pk":"107237","name":"旧加藤家住宅主屋","kana":"きゅうかとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県大洲市大洲字三ノ丸848-1","lat":33.50693972,"lng":132.54076941,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積137㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"38 － 0073","desc":"大洲城三の丸南隅櫓の敷地内に建つ。桁行１２ｍ，梁間１０ｍの規模，木造２階建，寄棟造とする。玄関は南面に切妻造で突出する。２階は中廊下を南北に通し部屋を配す。三方を縁側とし，ガラス障子の開放的なつくりで，戦前の旧大名家の暮らしぶりが窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006253"},{"id":"00002697","register_sub_id":"101","register_pk":"103687","name":"旧川之石浦庄屋二宮家住宅石塀","kana":"きゅうかわのいしうらしょうやにのみやけじゅうたくいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県八幡浜市保内町川之石3番耕地10-1","lat":33.47770944,"lng":132.39545648,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、延長33m","structure_material":"石造","registered":"2002.02.14(平成14.02.14)","register_no":"38 － 0024","desc":"町の中心部にある旧庄屋宅の外塀。大小様々な緑泥片石を鋭角で組み合わせ，全体として矢筈積に近い造りとする。旧敷地側で大規模な石を積み平石で頂部を整える一方，裏側では小規模な石をより不規則に積む。矢筈積が完成する前の石造技術を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002697"},{"id":"00015260","register_sub_id":"101","register_pk":"530684","name":"旧佐野家住宅（商いと暮らし博物館）主屋","kana":"きゅうさのけじゅうたく（あきないとくらしはくぶつかん）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県喜多郡内子町内子1938","lat":33.55219722,"lng":132.65262222,"geo_status":"db","era":"江戸末期／明治中期・同43年増築、昭和前期・同63年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積216㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"38 - 0194","desc":"大洲街道に北面し、かつて酒造業や薬種業を営んだ商家の主屋。２階建切妻造桟瓦葺で正面に庇を通す。内部は東に土間を通して、西に二列の居室を配し、南西は床、違い棚、平書院を備えた上質な座敷。幕末と明治の建物を一棟に改修した町家で町の発展を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015260"},{"id":"00015261","register_sub_id":"101","register_pk":"530685","name":"旧佐野家住宅（商いと暮らし博物館）土蔵","kana":"きゅうさのけじゅうたく（あきないとくらしはくぶつかん）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県喜多郡内子町内子1938","lat":33.552025,"lng":132.65278333,"geo_status":"db","era":"明治後期／昭和63年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積99㎡","structure_material":"土蔵造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"38 - 0195","desc":"坪庭を挟んで主屋南西に位置するかつての酒蔵。二階建切妻造妻入で北と南に戸口を開け、外壁漆喰塗仕上。内部各階一室で一階は土間、二階は板敷、北東に階段を配す。中央の２本の独立柱で地棟を受け、小屋組は登梁形式。主屋とともに敷地景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015261"},{"id":"00015262","register_sub_id":"101","register_pk":"530686","name":"旧佐野家住宅（商いと暮らし博物館）離れ","kana":"きゅうさのけじゅうたく（あきないとくらしはくぶつかん）はなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県喜多郡内子町内子1938","lat":33.55200833,"lng":132.65291667,"geo_status":"db","era":"昭和7年頃／昭和63年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積60㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"38 - 0196","desc":"敷地中央に西面して建つ離れ。二階建入母屋造桟瓦葺で南東に便所棟を延ばす。各階二室を配し、一階は東室、二階は西室に床構え付き座敷とする。一階座敷は南庭に面して縁を付し、ガラス戸を建て時代相を示す。主屋と一体となって敷地内の景観をつくる離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015262"},{"id":"00006259","register_sub_id":"101","register_pk":"107243","name":"旧下芳我家住宅隠居屋","kana":"きゅうしもはがけじゅうたくいんきょや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県喜多郡内子町内子1949","lat":33.55271031,"lng":132.6532533,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造2階一部平屋建、瓦葺、建築面積123㎡、渡廊下付","structure_material":"木造2階一部平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"38 － 0075","desc":"主屋に東隣して建つ。木造２階建。南側に木造平屋建の離れが付く。床柱や棚板に銘木を用いるなど，部屋ごとに吟味した材料を使い，遊び心を感じる意匠が凝らされている。通りに面して入母屋破風を見せ，両脇には袖壁を出す。主屋と連担して町並み景観を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006259"},{"id":"00013892","register_sub_id":"101","register_pk":"507850","name":"旧鈴木家住宅主屋","kana":"きゅうすずきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県松山市三津一丁目174他","lat":33.86560833,"lng":132.71206111,"geo_status":"db","era":"大正後期／昭和38年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積102㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"38 － 0154","desc":"港町三津浜で通りに北面する。二階建切妻造桟瓦葺で正面に下屋を通し、上下階とも出桁造。一階に格子を建て、二階は軒まで塗込め、格子窓三所、洋風渦紋の袖壁や腰等を人造石洗出で仕上げる。内部は欄間に陶製の唐草模様を飾るなど、瀟洒な意匠を自由に展開。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013892"},{"id":"00013893","register_sub_id":"101","register_pk":"507851","name":"旧鈴木家住宅離れ","kana":"きゅうすずきけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"愛媛県","address":"愛媛県松山市三津一丁目174他","lat":33.86551667,"lng":132.71211389,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"木造平屋建、切妻造、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"38 － 0155","desc":"主屋後方に南北棟で建ち、廊下で繋ぐ平屋建切妻造桟瓦葺。北に六畳茶室、南に四畳次の間を配し、西面は掃出しで落縁に銅板葺の庇を付す。茶室は東面に床と地袋付床脇を備え、北面西端に躙口を開き、簾天井を張る。開放的で、丸太を多用した数寄屋意匠の離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013893"},{"id":"00014964","register_sub_id":"101","register_pk":"519224","name":"旧髙橋家住宅石垣及び土塀","kana":"きゅうたかはしけじゅうたくいしがきおよびどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県喜多郡内子町内子2403","lat":33.553725,"lng":132.65543889,"geo_status":"db","era":"江戸後期／昭和3年頃増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石垣 石造、総延長69m 塀 土塀、瓦葺、総延長40m","structure_material":"石垣 石造","registered":"2024.03.06(令和6.03.06)","register_no":"38 - 0185","desc":"敷地正側面を廻る石垣及び土塀。石垣は最大高さ2・5メートル、総延長69メートル。玉石の乱積で隅は割石の算木積とする。西側は比較的平らな石を斜めに積んだ谷積風とする。土塀は桟瓦葺で壁漆喰塗仕上とし、石垣と一体で旧家の風格ある屋敷構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014964"},{"id":"00014965","register_sub_id":"101","register_pk":"519225","name":"旧髙橋家住宅井戸","kana":"きゅうたかはしけじゅうたくいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県喜多郡内子町内子2403","lat":33.55390278,"lng":132.65533611,"geo_status":"db","era":"文政10年(1827)","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"石造、面積1.4㎡","structure_material":"石造","registered":"2024.03.06(令和6.03.06)","register_no":"38 - 0186","desc":"主屋の西、離れの北に位置する石組の井戸。井戸枠は一・二メートル四方。高さ53センチメートル、厚さ19センチメートルの花崗岩切石4枚を相欠で精緻に組合わせる。井筒は内径100センチメートルの玉石積とする。石工技術に優れた丁寧なつくりの井戸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014965"},{"id":"00014963","register_sub_id":"101","register_pk":"519223","name":"旧髙橋家住宅表門","kana":"きゅうたかはしけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"愛媛県","address":"愛媛県喜多郡内子町内子2403","lat":33.55375,"lng":132.6555,"geo_status":"db","era":"昭和26年頃","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造、瓦葺、間口2.1m、左右袖塀付","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"38 - 0184","desc":"通りに面した敷地南辺の中央東寄りに建つ、間口2・1メートルの一間一戸の腕木門。切妻造桟瓦葺で、背面に控柱を立て、軒は一軒疎垂木とし、門口には板戸を吊る。左右に袖塀を付け、西袖塀には潜戸を設ける。正面石段とともに旧家の表構えを形成する表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014963"},{"id":"00014961","register_sub_id":"101","register_pk":"519221","name":"旧髙橋家住宅主屋","kana":"きゅうたかはしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"愛媛県","address":"愛媛県喜多郡内子町内子2403","lat":33.55384722,"lng":132.65551111,"geo_status":"db","era":"昭和26年頃／平成8年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積194㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"38 - 0182","desc":"小田川右岸の高台に位置する旧家の主屋。入母屋造桟瓦葺平入で南面中央に玄関を付す。内部は戦後に軸部を取替え改修し、玄関の東に出窓付の洋室や12畳の広縁付き座敷を配する。伝統的な外観を残しつつ接客空間を充実した戦後の和洋折衷住宅の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014961"},{"id":"00014962","register_sub_id":"101","register_pk":"519222","name":"旧髙橋家住宅離れ","kana":"きゅうたかはしけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県喜多郡内子町内子2403","lat":33.55379444,"lng":132.655325,"geo_status":"db","era":"昭和3年頃／平成14年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積132㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"38 - 0183","desc":"敷地南西隅に建つ離れ。二階建入母屋造桟瓦葺で、東に入母屋造玄関を付す。一階は玄関から北西に中廊下を通して、南西に座敷や仏間を配す。二階南の続き間座敷は西と南の窓から小田川を望み、北東に矩折れに床と棚を設け、床框など銘木を用いた上質なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014962"},{"id":"00014693","register_sub_id":"101","register_pk":"515235","name":"旧村上家住宅主屋","kana":"きゅうむらかみけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県大洲市大洲字志保町東379","lat":33.50665278,"lng":132.54840556,"geo_status":"db","era":"明治2年頃／昭和57年頃・令和元年改修","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造2階建、瓦葺、建築面積165㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"38 - 0178","desc":"大洲城下の志保町通に西面する木蝋業を営んだ町家。二階建切妻造平入桟瓦葺で下屋を付し、二階外壁は漆喰塗仕上大壁と出格子構えとする。内部一階に中土間を通し南東に床構え付き座敷、二階南に三間続きの座敷を配す。間口長大で地域の歴史的景観を造る町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014693"},{"id":"00014695","register_sub_id":"101","register_pk":"515237","name":"旧村上家住宅土蔵","kana":"きゅうむらかみけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県大洲市大洲字志保町東379","lat":33.50661667,"lng":132.54857222,"geo_status":"db","era":"明治中期／令和元年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積34㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"38 - 0180","desc":"主屋背後に中庭を介して位置し、敷地裏通りに面する土蔵。切石積基礎上に建つ、二階建切妻造平入桟瓦葺で、土蔵造漆喰仕上とし、腰を海鼠壁とする。内部各階とも板敷の一室で、西辺に階段を設ける。肱川水害に備えて床高を上げ、海鼠壁など丁寧な造りの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014695"},{"id":"00014694","register_sub_id":"101","register_pk":"515236","name":"旧村上家住宅付属屋","kana":"きゅうむらかみけじゅうたくふぞくや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県大洲市大洲字志保町東379","lat":33.50671944,"lng":132.54841111,"geo_status":"db","era":"江戸末期／令和元年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積32㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"38 - 0179","desc":"大洲城下の志保町通に西面する主屋の北に建つ町家。二階建、切妻造平入桟瓦葺で、出桁造の下屋を付し、二階前面は出窓として手摺を付す。内部一階は前土間形式で二階は二室で西室を床構え付座敷とする。主屋と一体となって通り沿いの歴史的景観を造る町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014694"},{"id":"00014536","register_sub_id":"101","register_pk":"513950","name":"久保家住宅表門及び塀","kana":"くぼけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県松山市道後湯之町919-1","lat":33.85051944,"lng":132.78566667,"geo_status":"db","era":"明治39年頃／令和3年改修","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"表門 木造、瓦葺、間口3.5m 塀 木造、瓦葺、総延長26m","structure_material":"表門 木造","registered":"2023.02.27(令和5.02.27)","register_no":"38 - 0169","desc":"伊佐爾波神社参道に開く開業医の屋敷表門。切妻造桟瓦葺の腕木門で袖壁付。軒は疎垂木木舞打、東袖に脇戸、欄間は横連子。扉の表は一枚板に框を廻し金具を付けず、抑制を効かせて重厚感がある。鼠漆喰腰板張の塀を左右に延ばし、落ち着いた歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014536"},{"id":"00014533","register_sub_id":"101","register_pk":"513947","name":"久保家住宅主屋","kana":"くぼけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県松山市道後湯之町919-1","lat":33.85041111,"lng":132.78571389,"geo_status":"db","era":"明治39年頃／昭和47年・令和元年改修","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積183㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"38 - 0166","desc":"伊佐爾波神社参道に北面する開業医の和風住宅。寄棟造桟瓦葺の平屋建、四周に下屋、元檜皮葺の切妻造玄関を構える。玄関西脇に二畳台目茶室を設け、東に付書院床構えの続き間座敷を配す。西奥は内向きの室。玄関破風の鳳凰懸魚は道後の和風建築に相応しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014533"},{"id":"00014537","register_sub_id":"101","register_pk":"513951","name":"久保家住宅仕切門及び塀","kana":"くぼけじゅうたくしきりもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県松山市道後湯之町919-1","lat":33.85049444,"lng":132.78572778,"geo_status":"db","era":"明治39年頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"仕切門 木造、銅板葺、間口1.8m 塀 木造、瓦葺、総延長7.8m","structure_material":"仕切門 木造","registered":"2023.02.27(令和5.02.27)","register_no":"38 - 0170","desc":"医家の屋敷内で敷地の玄関側と座敷側を隔てる塀と、それに開く門。切妻造銅板葺の腕木門で、軒は疎垂木、扉は舞良戸を建てる。塀は桟瓦葺、真壁造鼠漆喰仕上で、通り沿いの塀の裏側と仕様を揃え接続する。旧家の屋敷内の落ち着きある接客空間を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014537"},{"id":"00014534","register_sub_id":"101","register_pk":"513948","name":"久保家住宅離れ","kana":"くぼけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県松山市道後湯之町918-1","lat":33.85050278,"lng":132.78583056,"geo_status":"db","era":"大正3年頃／昭和3年・同24年・平成23年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積40㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"38 - 0167","desc":"伊佐爾波神社参道にある開業医屋敷の北東角に位置する離れ。入母屋造桟瓦葺の二階建、二階の主屋側を手摺付ガラス戸で開放的にし、霧除庇を付す。内部は各階東西二室、東室中央寄りに階段を設け、一階は元薬品庫、二階は続き間座敷とする。歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014534"},{"id":"00014535","register_sub_id":"101","register_pk":"513949","name":"久保家住宅待合","kana":"くぼけじゅうたくまちあい","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県松山市道後湯之町919-1","lat":33.85050556,"lng":132.78561111,"geo_status":"db","era":"明治39年頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造、瓦葺、面積2.2㎡","structure_material":"木造","registered":"2023.02.27(令和5.02.27)","register_no":"38 - 0168","desc":"医家の屋敷北西に位置する供待で、表門と主屋茶室へ飛石で繋ぐ。切妻造桟瓦葺軒先銅板で招き屋根とし、化粧屋根裏は杉皮に竹小舞打、柱は節丸太、壁は中塗仕上とする。通り側の壁を深く、茶室側を浅く取り動線に配慮し、雑木を用いる軒桁の架構に工夫がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014535"},{"id":"00008791","register_sub_id":"101","register_pk":"149512","name":"河内家住宅井戸","kana":"こうちけじゅうたくいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県喜多郡内子町五百木123-1","lat":33.56361831,"lng":132.65988736,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造、面積1.6㎡、上屋付","structure_material":"石造","registered":"2011.07.25(平成23.07.25)","register_no":"38 － 0101","desc":"主屋の南に位置する。四本の花崗岩切石を井桁に組み枠石とし、方1.3ｍ高さ0.52ｍとする。地下は玉石を円形に並べて築く。周囲に大振りの青石を貼り洗い場とする。その四方に方柱をたて、切妻造桟瓦葺屋根を造る。明治期の生活の一端が窺える施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008791"},{"id":"00008789","register_sub_id":"101","register_pk":"149510","name":"河内家住宅主屋","kana":"こうちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県喜多郡内子町五百木123-1","lat":33.56379794,"lng":132.65982454,"geo_status":"db","era":"明治27年／昭和前期・昭和中期改修","year":1894,"year_source":"converted","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積195㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"38 － 0099","desc":"中山川沿いの集落に位置する。西面して建つ木造つし2階建。入母屋造桟瓦葺とし、周囲に下屋庇をまわす。正面中央に出格子、南に土間玄関、北に式台を構える。北端に前後に座敷を配し、奥室に座敷飾りを備える。近代の大規模な農家建築で、上質な座敷を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008789"},{"id":"00008790","register_sub_id":"101","register_pk":"149511","name":"河内家住宅土蔵","kana":"こうちけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県喜多郡内子町五百木123-1","lat":33.56370502,"lng":132.66001283,"geo_status":"db","era":"明治中期／平成9年頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積60㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"38 － 0100","desc":"主屋の東南に位置し、東西棟で建つ。桁行9.9ｍ梁間5.0ｍの木造2階建、切妻造桟瓦葺とし、北面に庇を付ける。外壁は大壁とし、軒まわりは木部を現す。2階は1室で、1階は東西に3室が並ぶ。中央を板間、他を土間とする。上層農家屋敷を構成する一要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008790"},{"id":"00005041","register_sub_id":"101","register_pk":"106031","name":"古今荘","kana":"ここんそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県四国中央市上分町601-2","lat":33.99418121,"lng":133.58770555,"geo_status":"db","era":"明治初期／明治30頃移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"38 － 0065","desc":"東西に長い敷地の中央北寄りに建つ。桁行９間，梁間５間，入母屋造，本瓦葺，妻入，木造平屋建で，床の間の付属した１５畳の上之間，次之間，三之間を並べ，間口２間半の式台玄関の上部はむくり破風の屋根を付ける。接客部分を中心とした庄屋屋敷の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005041"},{"id":"00003717","register_sub_id":"101","register_pk":"104707","name":"篠永酒造土蔵","kana":"しのながしゅぞうどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県四国中央市具定町正之森250-1","lat":33.96816839,"lng":133.52544794,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積17㎡","structure_material":"土蔵造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"38 － 0046","desc":"主屋の背面に南北棟で建つ道具蔵。切妻造，桟瓦葺，平入の土蔵造平屋建で，平側に鉄格子を嵌め込んだ窓を配する。腰部に施された七宝文の海鼠壁や，窓庇を受ける雲形の持ち送りなど丁寧な左官仕事に見所がある。小規模ながらも，左官技術に優れた建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003717"},{"id":"00003160","register_sub_id":"101","register_pk":"104150","name":"末永家住宅旧主屋","kana":"すえながけじゅうたくきゅうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県大洲市長浜甲309","lat":33.6115829,"lng":132.48007349,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積177㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0037","desc":"回漕業を営み，地元にも重きをなした末永家による建築。棟梁は地元の隅田弥太郎と伝える。１階には石を用い，２階腰部になまこ壁を設け，２階屋根を支える持ち送りや窓廻りを漆喰細工とするなど特徴ある外観をもつ他，内部装飾にも見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003160"},{"id":"00003161","register_sub_id":"101","register_pk":"104151","name":"末永家住宅百帖座敷","kana":"すえながけじゅうたくひゃくじょうざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県大洲市長浜甲312-1","lat":33.61163827,"lng":132.480225,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0038","desc":"敷地奥の北側に建つ。入母屋造，桟瓦葺で，共に１８畳敷の座敷と次の間を持ち，次の間には５畳の前室を備え，庭側に縁を通す。次の間は棹縁天井，座敷は折上格天井であるが，若干の洋風装飾も備える。大回漕業主住宅の接客施設として欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003161"},{"id":"00015389","register_sub_id":"101","register_pk":"532513","name":"仙波家住宅主屋","kana":"せんばけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県松山市北久米町394","lat":33.81794167,"lng":132.79949444,"geo_status":"db","era":"明治33年／平成元年・同4年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積160㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"38 - 0197","desc":"松山市街地の東部に位置する農家の主屋。敷地中央に南面して建つ入母屋造桟瓦葺でつし二階建とする。東に土間、西に居室を配し、南西隅の座敷は北面に床を構え、南・西面に内縁と濡縁を廻す。付書院に櫛形火灯窓を開け、繊細な組子の欄間を建てるなど上質。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015389"},{"id":"00015390","register_sub_id":"101","register_pk":"532514","name":"仙波家住宅露地門及び塀","kana":"せんばけじゅうたくろじもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県松山市北久米町394","lat":33.81785833,"lng":132.79945556,"geo_status":"db","era":"明治33年頃","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"露地門 木造、瓦葺、間口1.4m 塀 木造、瓦葺、総延長7.7m、土塀付","structure_material":"露地門 木造","registered":"2025.03.13(令和7.03.13)","register_no":"38 - 0198","desc":"主屋南側の庭園への出入口となる露地門と両脇に続く塀。露地門は一間の薬医門。屋根は切妻造本瓦葺で箱棟胴板瓦に波をあしらい、棟両端に鯱瓦を載せた華やかな門。門の両脇は本瓦葺の板塀で、南辺を桟瓦葺の土塀とし、露地門とともに屋敷正面の構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015390"},{"id":"00001758","register_sub_id":"101","register_pk":"102748","name":"一柳陣屋門","kana":"ひとつやなぎじんやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県四国中央市川之江町2527","lat":34.01766672,"lng":133.57605166,"geo_status":"db","era":"江戸初期","year":1632,"year_source":"estimated","year_min":1615,"year_max":1650,"year_label":"江戸初期","structure":"木造2階建、瓦葺、建築面積34㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"38 － 0007","desc":"寛永年間に川之江を治めた一柳直家が建設した陣屋の表門と伝え，直家没後に天領となり，川之江八幡神社に移されたと考えられる。入母屋造，総２階建で，１階左を門構え，右を詰所とし，２階は２室にわける。地方の小藩における陣屋建築の一端を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001758"},{"id":"00004832","register_sub_id":"101","register_pk":"105822","name":"兵藤家住宅主屋","kana":"ひょうどうけじゅたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県大洲市長浜町出海乙9-1","lat":33.55759234,"lng":132.4333813,"geo_status":"db","era":"江戸末期／明治初期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積207㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"38 － 0061","desc":"庄屋を務めた旧家の住宅主屋で，１２畳・８畳・８畳を南北一列に並べ，西・北に縁を廻らせた入母屋造の座敷棟と，８畳３室と土間等から構成される入母屋造の住居棟とを雁行形に配置する。座敷棟の２間幅の式台や北端８畳の座敷飾りが当家の格式を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004832"},{"id":"00004835","register_sub_id":"101","register_pk":"105825","name":"兵藤家住宅外塀","kana":"ひょうどうけじゅたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県大洲市長浜町出海乙9-1","lat":33.55777583,"lng":132.43333889,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、延長80m","structure_material":"土塀","registered":"2005.07.12(平成17.07.12)","register_no":"38 － 0064","desc":"屋敷地の北半を囲う外塀で，西面のほぼ中央に門口を開け，北面のほぼ中央と西面の南寄りから主屋座敷棟に向けて内塀を延ばし，座敷前の庭園を囲う。緑泥片岩の青石を積んだ石垣の上に築かれた２尺厚の重厚な屋根付土塀で門とともに風格ある屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004835"},{"id":"00004833","register_sub_id":"101","register_pk":"105823","name":"兵藤家住宅土蔵","kana":"ひょうどうけじゅたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県大洲市長浜町出海乙9-1","lat":33.55738861,"lng":132.43343263,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"38 － 0062","desc":"主屋住居棟の南東方に位置し，東西棟で建つ。桁行５間梁間３間規模，切妻造，桟瓦葺，平入の２階建土蔵で，北面に下屋庇を差し掛けて２戸口を開ける。外壁は腰高な縦板張とし，軒には鉢巻きを廻す。妻面に小さな窓を開けた閉鎖的な蔵で，主屋背後の構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004833"},{"id":"00004834","register_sub_id":"101","register_pk":"105824","name":"兵藤家住宅門","kana":"ひょうどうけじゅたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県大洲市長浜町出海乙9-1","lat":33.55764317,"lng":132.43318501,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.5m","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"38 － 0063","desc":"屋敷地西側の道路に面し，道路からの石段を上がったところに南北棟で建つ。間口２．５ｍ，切妻造，桟瓦葺，１間１戸の棟門で，石段の南北の土塀との間に木造の袖塀を廻す。主屋座敷棟の式台玄関に対応した表門で，屋敷正面の構えに欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004834"},{"id":"00003158","register_sub_id":"101","register_pk":"104148","name":"ふるさと旅行村隠居屋","kana":"ふるさとりょこうむらいんきょや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県上浮穴郡久万高原町下畑野川乙488","lat":33.67328477,"lng":132.93771239,"geo_status":"db","era":"明治38／昭和55移築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0035","desc":"隠居屋として建てられた住居建築。桁行４間半，梁間２間半の小規模な作りで，入母屋造，桟瓦葺とする。基礎部は丸石を並べて土台を廻し，柱を立てている。近隣では別棟の隠居屋を建てる習慣があったと伝えられ，農村の住宅のあり方を今日に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003158"},{"id":"00003154","register_sub_id":"101","register_pk":"104144","name":"ふるさと旅行村旧石丸家住宅主屋","kana":"ふるさとりょこうむらきゅういしまるけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県上浮穴郡久万高原町下畑野川乙488","lat":33.67292297,"lng":132.93723925,"geo_status":"db","era":"江戸後期／昭和52移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積137㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0031","desc":"構造形式等から江戸時代後期の建築と思われる民家。屋根は茅葺。当初所在地の近隣には藩有林があり，代官の視察時の宿泊所としても使われたと伝えられ，十二畳の大座敷を取るなど格式を誇る。江戸期の上層農民の生活を今日に伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003154"},{"id":"00003157","register_sub_id":"101","register_pk":"104147","name":"ふるさと旅行村旧渡邊家住宅主屋","kana":"ふるさとりょこうむらきゅうわたなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県上浮穴郡久万高原町下畑野川乙488","lat":33.67341086,"lng":132.93724083,"geo_status":"db","era":"明治12／昭和55移築","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、茅葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0034","desc":"明治１２年建築の比較的大規模な農家建築。屋根は茅葺で，田の字型平面を持つ。上座側は開放的な作りとし，土間部の壁面は腰部板張，上部白壁とし，妻面にも戸口を開く。茅葺の大きな屋根面が特徴的で，付近の明治期の農村景観を旅行村内に再現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003157"},{"id":"00003155","register_sub_id":"101","register_pk":"104145","name":"ふるさと旅行村土蔵","kana":"ふるさとりょこうむらどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県上浮穴郡久万高原町下畑野川乙488","lat":33.6730723,"lng":132.93728287,"geo_status":"db","era":"明治3／昭和51移築","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"土蔵造2階建、茅葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0032","desc":"穀物貯蔵のための土蔵。内部には２階を設け，什器などを納めている。外部は扉上部の庇高さまで板張とし，それより上は漆喰塗で，鉢巻隅には装飾を設けている。屋根は置屋根形式，茅葺で，地域の農村景観のかっての有様を今日に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003155"},{"id":"00012452","register_sub_id":"101","register_pk":"531776","name":"宮内家住宅隠居所","kana":"みやうちけじゅうたくいんきょじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県伊予市灘町123","lat":33.7577,"lng":132.7009,"geo_status":"db","era":"明治45年頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積96㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"38-123","desc":"主屋後方に東西棟で建つ。入母屋造桟瓦葺の二階建、上下階とも八畳二室で一階座敷の床は三段の霞棚と丸窓を組合わせる。南・東面に縁を廻らし、垂木は丸太を使い、二階は扇垂木として欄間に丸い下地窓を千鳥に配する。上質かつ洗練された意匠の隠居屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012452"},{"id":"00012454","register_sub_id":"101","register_pk":"531778","name":"宮内家住宅潮見堀","kana":"みやうちけじゅうたくしおみぼり","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県伊予市灘町123-1","lat":33.75764722,"lng":132.70065556,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、面積8.7㎡","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"38-125","desc":"敷地の港側となる古隠居西方にある。台形平面で深さ約1･5メートルの堀の西側に出入用の石段をつくる。扁平で丸みのある緑泥片岩を平積みし、大振りの石を適宜挿入する。かつては港の潮の干満を堀の中の水位変化で観察した。類例稀な住宅内の検潮施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012454"},{"id":"00012451","register_sub_id":"101","register_pk":"531775","name":"宮内家住宅主屋","kana":"みやうちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県伊予市灘町123","lat":33.75763611,"lng":132.70145278,"geo_status":"db","era":"江戸中期／平成28年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積255㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"38-122","desc":"通りに東面して建つ。間口の広いつし二階建で、下屋を設け、直交する屋根を千鳥破風風にみせる。正面は出格子と簓子下見板張で、上部を出桁造の軒まで塗籠めて格子窓を穿つ。北側を土間、南側を三列構成として上手列を座敷とする。重厚な趣の大型町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012451"},{"id":"00012453","register_sub_id":"101","register_pk":"531777","name":"宮内家住宅古隠居","kana":"みやうちけじゅうたくふるいんきょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県伊予市灘町123","lat":33.75764444,"lng":132.70075833,"geo_status":"db","era":"文化9年（1812）","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"38-124","desc":"敷地の西奥に南北棟で建つ。切妻造桟瓦葺で、南端を八畳の主室として東西に縁側を通し、北に四畳や三畳を配する。八畳は柱・長押を面皮材とし、南面の床脇に大振りの円窓を穿ち、鏡天井に龍図、同じく四畳に舞鶴を描く。古雅な佇まいの隠居屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012453"},{"id":"00009402","register_sub_id":"101","register_pk":"194195","name":"明星草庵","kana":"みょうじょうそうあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県北宇和郡鬼北町大字下鍵山432","lat":33.33508812,"lng":132.79774282,"geo_status":"db","era":"大正期／平成2年移築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、茅葺、建築面積91㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"38 － 0108","desc":"南面して建つ木造平屋建。桁行一三・〇メートル梁間七・〇メートル、入母屋造茅葺である。八畳二室と土間からなり、南西面に縁を廻らせ、土間に板の間を張出す。良質なケヤキ材などを使用した小規模な茅葺民家で、愛媛県山間部の民家形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009402"},{"id":"00015094","register_sub_id":"101","register_pk":"529372","name":"村上家住宅御成門及び東塀","kana":"むらかみけじゅうたくおなりもんおよびひがしべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県新居浜市大島甲137","lat":33.99568889,"lng":133.36558333,"geo_status":"db","era":"江戸中期／明治4年頃改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"御成門 木造、瓦葺、間口2.4m、袖塀付 東塀 土塀、瓦葺、総延長12m","structure_material":"御成門 木造","registered":"2024.08.15(令和6.08.15)","register_no":"38 - 0189","desc":"表門の東に建つ御成門とその東から北へ折れ曲がる土塀。御成門は切妻造平入本瓦葺で門口に両開板扉を吊り、欄間は横連子とする。東塀は折曲がり延長８・３メートル、桟瓦葺屋根で外壁は白漆喰塗仕上とする。表門と並び建ち旧家の格式ある屋敷構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015094"},{"id":"00015093","register_sub_id":"101","register_pk":"529371","name":"村上家住宅表門及び南塀","kana":"むらかみけじゅうたくおもてもんおよびみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県新居浜市大島甲137","lat":33.99568333,"lng":133.3655,"geo_status":"db","era":"江戸中期／明治4年頃改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"表門 木造、瓦葺、間口3.8m 南塀 土塀、瓦葺、総延長18m","structure_material":"表門 木造","registered":"2024.08.15(令和6.08.15)","register_no":"38 - 0188","desc":"主屋前方に建つ表門とその両脇に延びる塀。表門は切妻造平入桟瓦葺で冠木上に束を立て棟木を受ける。門口には両開板扉を吊り、西脇に潜戸を設ける。南塀は桟瓦葺土塀で外壁は漆喰仕上、腰はモルタル塗仕上。通りに面し間口広い門構えとし、旧家の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015093"},{"id":"00015092","register_sub_id":"101","register_pk":"529370","name":"村上家住宅主屋","kana":"むらかみけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県新居浜市大島甲137","lat":33.99578889,"lng":133.365475,"geo_status":"db","era":"江戸中期／明治4年頃改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積192㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"38 - 0187","desc":"大島の集落中心部にある旧家の主屋。敷地中央に南面するつし二階建入母屋造平入本瓦葺で、南面東寄りに起り付き切妻屋根の式台玄関を構える。内部は西に土間、東に二列四室並べ、南東に角座敷を延ばす。塗込出格子を付した重厚な外観が旧家の風格を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015092"},{"id":"00014692","register_sub_id":"101","register_pk":"515234","name":"森家住宅御成門及び塀","kana":"もりけじゅうたくおなりもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県西条市氷見字上町丙658-2","lat":33.89201389,"lng":133.12795278,"geo_status":"db","era":"文久4年（1864）頃","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"門 木造、瓦葺、間口1.7m 塀 木造、瓦葺、総延長25m","structure_material":"門 木造","registered":"2023.08.07(令和5.08.07)","register_no":"38 - 0177","desc":"石鎚山への街道から引き込んで藩主専用に建てた御成門。屋敷北西に位置する切妻造桟瓦葺の腕木門と、街道沿いに主屋まで延びる目板瓦葺腰板張の土塀。門は疎垂木小舞打、大瓶束笈形、女梁繰形付、門扉は八双金物付の本格的な形式で、湯殿廻りの格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014692"},{"id":"00014688","register_sub_id":"101","register_pk":"515230","name":"森家住宅主屋","kana":"もりけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県西条市氷見字上町丙658-2","lat":33.89183333,"lng":133.127825,"geo_status":"db","era":"天保12年（1841）","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"木造2階建、瓦葺、建築面積400㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"38 - 0173","desc":"石鎚山への街道沿いにある旧家。主屋は切妻造平入桟瓦葺、二階建二棟を並置して谷樋で繋ぐ。表棟上手に角屋座敷を設けて上段の間とし、通りに幅二間の式台及び床構え付玄関を構える格式有る造り。街道に面して長大な屋敷構えで江戸時代の景観を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014688"},{"id":"00014689","register_sub_id":"101","register_pk":"515231","name":"森家住宅庭座敷及び塀","kana":"もりけじゅうたくにわざしきおよびへい","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県西条市氷見字上町丙658-2","lat":33.89173889,"lng":133.12774167,"geo_status":"db","era":"江戸末期／昭和後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"庭座敷 木造平屋建、瓦葺、建築面積55㎡ 塀 木造、瓦葺、延長11m","structure_material":"庭座敷 木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"38 - 0174","desc":"石鎚山への街道沿いに位置する旧家の座敷棟と土塀。入母屋造桟瓦葺の平屋建、主屋の表棟下手に接続する。床構え付八畳と出格子窓付の十二畳で構成し、庭側に濡縁を通す。床構えは簡素で普段使いの客間と考える。塀を連ねて街道沿いの歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014689"},{"id":"00014690","register_sub_id":"101","register_pk":"515232","name":"森家住宅離れ","kana":"もりけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県西条市氷見字上町丙658-2","lat":33.891775,"lng":133.12804167,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"38 - 0175","desc":"旧氷見町の旧家の隠居屋。主屋二棟の背後に繋がる入母屋造桟瓦葺の真壁造平屋建。内部は田の字型間取で、床構え付八畳間、下地窓を開けた四畳半茶室を備え、濡縁を巡らし瓦葺の庇を架ける。豪壮な瓦屋根外観の一方で、内部は長押を用いず質素な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014690"},{"id":"00014691","register_sub_id":"101","register_pk":"515233","name":"森家住宅湯殿","kana":"もりけじゅうたくゆどの","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県西条市氷見字上町丙658-2","lat":33.89201667,"lng":133.12786389,"geo_status":"db","era":"天保12年（1841）頃","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"38 - 0176","desc":"石鎚山への街道沿いにある旧家の湯殿。石垣で一段高い位置に建つ入母屋造桟瓦葺の平屋建で、主屋上段の間に渡廊下で接続する。中廊下を通し、街道側を厠として木製便器、庭側を出格子窓付の湯殿として木製湯船を置く。内外共に歴史的景観をそのまま留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014691"},{"id":"00010695","register_sub_id":"101","register_pk":"201269","name":"八束家住宅蔵","kana":"やつづかけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県松山市持田町3-242-1","lat":33.843888,"lng":132.781365,"geo_status":"db","era":"明治中期／昭和11年移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"38－0112","desc":"敷地北西隅に建つ。桁行二間半梁間二間、土蔵造二階建、切妻造桟瓦葺である。東を戸口として庇を付け、南に倉庫を附属する。外壁は上部を黒漆喰塗で、腰部をモルタル塗洗出仕上げとする。倉庫は真壁造で腰を杉皮張とする。屋敷北西隅の景観を構成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010695"},{"id":"00010694","register_sub_id":"101","register_pk":"201268","name":"八束家住宅主屋","kana":"やつづかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県松山市持田町3-242-1","lat":33.843718,"lng":132.781476,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積198㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"38－0111","desc":"松山城東の住宅街に位置する。木造平屋建で、東に開く玄関の北に洋間、南に茶室を配する。玄関奥には二室続きの座敷を配し、南を畳敷とし庭に面する。数寄屋を基調とした意匠で端正にまとめられ、戦災を免れた当地における戦前期の洋間付住宅の希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010694"},{"id":"00010696","register_sub_id":"101","register_pk":"201270","name":"八束家住宅待合","kana":"やつづかけじゅうたくまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県松山市持田町3-242-1","lat":33.843528,"lng":132.78153,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺一部鋼板葺、建築面積8.6㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"38－0113","desc":"主屋茶室の南向かいに庭を挟んで建つ。腰掛と雪隠を背中合わせにした形式で、屋根は桟瓦の周囲に銅板を葺く。腰掛はＬ字に腰掛を廻らし、隅に琵琶棚風の棚を備える。要所にサルスベリを用いてアクセントとし、腰廻りや軒裏に杉皮を張るなど上質な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010696"},{"id":"00008787","register_sub_id":"101","register_pk":"149508","name":"山内家住宅倉","kana":"やまうちけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県四国中央市土居町入野983-2","lat":33.95630376,"lng":133.42116095,"geo_status":"db","era":"明治30年／昭和34年移築・平成19年改修","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積71㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"38 － 0097","desc":"通り沿いに南北棟で建つ。切妻造桟瓦葺、桁行12ｍ梁間5.9ｍの木造2階建。下部をモルタル仕上げ、上部を漆喰仕上げとし、隅を算木石積風に装飾。通り側に小庇付の窓を3所に設け、上部に福田幸平作という「玉を掴んだ龍」の鏝絵を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008787"},{"id":"00008786","register_sub_id":"101","register_pk":"149507","name":"山内家住宅離れ","kana":"やまうちけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県四国中央市土居町入野985-4他","lat":33.95606959,"lng":133.4212059,"geo_status":"db","era":"大正15年","year":1926,"year_source":"converted","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積211㎡","structure_material":"木造平屋一部2階建","registered":"2011.07.25(平成23.07.25)","register_no":"38 － 0096","desc":"通りの南に占める敷地に東面して建つ。中央に玄関を張り出し、南に平屋建、北に2階建を配する。入母屋造桟瓦葺、木造で、建築面積211㎡。1階は2列各4室を配し、周囲に縁をまわし、西前室に座敷飾りを備える。銘木を確かな技術で施工した近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008786"},{"id":"00003330","register_sub_id":"101","register_pk":"104320","name":"蕨岡家住宅主屋","kana":"わらびおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県南宇和郡愛南町正木1465","lat":33.00399327,"lng":132.68269911,"geo_status":"db","era":"明治33頃","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積228㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"38 － 0039","desc":"敷地のほぼ中央に建つ。東を正面とする木造・２階建，平入で，背面に角屋を延ばす。桟瓦葺の屋根は南が入母屋造，北が切妻造になり，東と南には下屋を廻す。全体に良材を用いた丁寧なつくりで，内外の木部に弁柄塗を施すなど，当地方の近代和風建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003330"},{"id":"00003332","register_sub_id":"101","register_pk":"104322","name":"蕨岡家住宅土蔵","kana":"わらびおかけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県南宇和郡愛南町正木1465","lat":33.00386992,"lng":132.68276489,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"38 － 0041","desc":"主屋の南側にある。土蔵造・２階建，南北棟の切妻造・桟瓦葺で，置屋根式になる。北面は１階中央に庇付きの戸口，２階には縦格子入の窓を設ける。外壁は漆喰塗であるが，腰は海鼠壁とし，その境に水切瓦をつけるなど，丁寧なつくりで，保存状態も良好である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003332"},{"id":"00003331","register_sub_id":"101","register_pk":"104321","name":"蕨岡家住宅長屋門","kana":"わらびおかけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県南宇和郡愛南町正木1465","lat":33.00396645,"lng":132.68284013,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"38 － 0040","desc":"桁行約２６ｍの細長い長屋門で，木造・平屋建，南北棟の切妻造・桟瓦葺で，中央を門構えとする。外壁は腰上を真壁造と漆喰大壁，腰を簓子下見板張と縦板張を巧みに組み合わせ，変化のある構成としている。街路側の屋敷東辺に建ち，集落の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003331"},{"id":"00003761","register_sub_id":"101","register_pk":"104751","name":"有沢家住宅蔵","kana":"ありさわけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡田野町2391-2","lat":33.42665745,"lng":134.00299642,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積13㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0118","desc":"主屋釜屋の南方，離れの東側に接して東西棟で建つ。桁行１間半梁間２間規模，切妻造，桟瓦葺，平入の２階建土蔵で，北面入口脇に１畳の物置を付属させる。腰を板張とし，上部を土佐漆喰塗壁に４段の水切瓦を付けた土佐特有の土蔵建築の外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003761"},{"id":"00003759","register_sub_id":"101","register_pk":"104749","name":"有沢家住宅主屋","kana":"ありさわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡田野町2391-2","lat":33.42692229,"lng":134.00301804,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積102㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0116","desc":"旧国道に北面する敷地に道路から退いて建つ。桁行４間梁間５間規模，東西棟，切妻造，桟瓦葺の木造２階建で，南北両面に下屋を付け，背後に釜屋と渡廊下を突出させる。西北に床付き３畳の式台玄関，西南に８畳の座敷を配した郷士住宅の系譜をひく網元の家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003759"},{"id":"00003760","register_sub_id":"101","register_pk":"104750","name":"有沢家住宅離れ","kana":"ありさわけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡田野町2391-2","lat":33.42665493,"lng":134.002899,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積31㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0117","desc":"主屋の南方に東西棟で建ち，主屋とは渡廊下で結ばれる。桁行３間梁間３間規模，切妻造，桟瓦葺の木造２階建で，１階は田野海岸の方に抜ける通り土間と６畳間，２階は６畳と４畳の２室とする。網元の住宅の屋敷構えを知る上で貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003760"},{"id":"00004449","register_sub_id":"101","register_pk":"105439","name":"泉家住宅主屋","kana":"いずみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県土佐市宇佐町宇佐1775-1","lat":33.45081799,"lng":133.442301,"geo_status":"db","era":"昭和22頃","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"木造2階建、瓦葺、建築面積92㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0163","desc":"昭和２１年の南海大地震により倒壊した家屋の再建。敷地北側道路に北面して建つ，桁行６間梁間３間規模，東西棟，切妻造，桟瓦葺の木造２階建で，２階は２０畳大の大広間となるつくりとする。震災前家屋を再現したもので，外部妻壁には５段の水切瓦を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004449"},{"id":"00008200","register_sub_id":"101","register_pk":"132641","name":"岩崎家住宅主屋","kana":"いわさきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸市井ノ口字杉ケ本甲1696他","lat":33.52616471,"lng":133.90000625,"geo_status":"db","era":"寛政7年（1795）頃／昭和55年改修","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造平屋建、茅葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0253","desc":"敷地中央に南面して建つ。桁行１２ｍ梁間９．４ｍの木造平屋建、寄棟造茅葺とし、正・背面に桟瓦葺下屋庇を付け、側面を葺き降ろす。西寄りを土間、東に食違い四間取の床上部を設ける。表座敷にはトコやトコ脇を構える。１８世紀に遡る小規模民家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008200"},{"id":"00008202","register_sub_id":"101","register_pk":"132727","name":"岩崎家住宅西蔵","kana":"いわさきけじゅうたくにしくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市井ノ口字杉ケ本甲1696他","lat":33.52628574,"lng":133.89985789,"geo_status":"db","era":"明治30年","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積93㎡","structure_material":"土蔵造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0255","desc":"東蔵の西に南北棟で建つ。桁行１１ｍ梁間４．８ｍの平屋建土蔵。寄棟造桟瓦葺とし、東面に奥行１．９ｍの庇を付け、東蔵との間には両下造屋根を架け、事務所や物入を造る。外壁は、腰竪板張の土佐漆喰仕上げの大壁とし、東蔵と一体で、重厚な屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008202"},{"id":"00008206","register_sub_id":"101","register_pk":"132731","name":"岩崎家住宅練塀","kana":"いわさきけじゅうたくねりへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市井ノ口字杉ケ本甲1696他","lat":33.52626818,"lng":133.90009214,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"練塀、瓦葺、延長15m","structure_material":"練塀","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0259","desc":"東蔵東北隅から東に延び、畑との境を南へ折れる。折曲り延長１５ｍ、厚さ０．６ｍ、高さ１．０ｍであるが、東面では敷地が低く、足下に大振りの石を積み、１．６ｍ高となる。イシグロと称する伝統的な練塀で、山石と赤土を用い、上部に桟瓦を葺く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008206"},{"id":"00008203","register_sub_id":"101","register_pk":"132728","name":"岩崎家住宅番屋","kana":"いわさきけじゅうたくばんや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸市井ノ口字杉ケ本甲1696他","lat":33.5260105,"lng":133.90022683,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積99㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0256","desc":"敷地の東南隅に所在する。建築面積９９㎡の木造平屋建。寄棟屋根と入母屋屋根を組み合わせ、南側に畳敷の居室を配し、北側に突出して土間の釜屋を設ける。土佐漆喰仕上げの真壁造で、屋根には左桟瓦と右桟瓦が葺かれる。農村景観に調和する簡明な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008203"},{"id":"00008204","register_sub_id":"101","register_pk":"132729","name":"岩崎家住宅便所","kana":"いわさきけじゅうたくべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"高知県","address":"高知県安芸市井ノ口字杉ケ本甲1696他","lat":33.52604173,"lng":133.90001991,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積7.1㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0257","desc":"主屋の南方で、江戸末期の屋敷地の東南隅に位置する。桁行３．３ｍ梁間２．１ｍの木造平屋建。南北棟の切妻造桟瓦葺で、西面を扉口とし、他三方を腰下見板張、上部土壁とする。三室に分け、大・小便所と物置とする。近世の農村における生活施設の一端を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008204"},{"id":"00008205","register_sub_id":"101","register_pk":"132730","name":"岩崎家住宅祠","kana":"いわさきけじゅうたくほこら","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸市井ノ口字杉ケ本甲1696他","lat":33.52645948,"lng":133.90011361,"geo_status":"db","era":"明治41年","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積2.6㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0258","desc":"屋敷地の北端の中央に南面して建つ。一間社流造桟瓦葺。自然石積の基壇上に土台を組み、柱を建てる。身舎は八角柱で、長押や貫で固め、軒桁や梁を直接に支持する。一軒疎垂木とし、妻は大瓶束。向拝は方柱、三斗組、中備蟇股。身舎正面に飾る三菱紋が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008205"},{"id":"00008201","register_sub_id":"101","register_pk":"132642","name":"岩崎家住宅東蔵","kana":"いわさきけひがしくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市井ノ口字杉ケ本甲1696他","lat":33.52628574,"lng":133.89999844,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0254","desc":"主屋の背面に東西棟で建つ。桁行１１ｍ梁間４．６ｍの２階建土蔵。切妻造桟瓦葺の置屋根で、南面に庇を掛け、作業場とする。１階内部は東西二室に分ける。腰に下見板を張る大壁造で、土佐漆喰仕上げで、数段の水切り瓦をまわすなど、土佐独特の外観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008201"},{"id":"00015095","register_sub_id":"101","register_pk":"529373","name":"岩村家住宅（旧黒岩家住宅）主屋","kana":"いわむらけじゅうたく（きゅうくろいわけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸市川北字前島甲284","lat":33.50371389,"lng":133.9318,"geo_status":"db","era":"江戸末期／明治23年頃・昭和50年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部二階建、瓦葺、建築面積101㎡","structure_material":"木造平屋一部二階建","registered":"2024.08.15(令和6.08.15)","register_no":"39 - 0315","desc":"用水が廻る前島集落中央部に建つ旧家の主屋。つし二階建桟瓦葺東西棟。南面下屋中央を玄関とし東西に内縁を付す。玄関四畳の東は六畳座敷で東に床構え、西は四畳半で戸棚をつくり、北列は東から六畳、居間、台所を配す。近世末期の郷士住宅の佇まいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015095"},{"id":"00015098","register_sub_id":"101","register_pk":"529376","name":"岩村家住宅（旧黒岩家住宅）瓦練塀","kana":"いわむらけじゅうたく（きゅうくろいわけじゅうたく）かわらねりべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸市川北字前島甲284-1","lat":33.50372778,"lng":133.93185833,"geo_status":"db","era":"江戸末期／明治中期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"練塀、瓦葺、総延長八・六m","structure_material":"練塀","registered":"2024.08.15(令和6.08.15)","register_no":"39 - 0318","desc":"主屋の東端から南と北に延びる瓦練塀。南塀は基礎に川原石を二段積とし、練塀の積土が薄く瓦が密な当地の仕様で、上部に軒唐草の桟瓦を葺く。北塀は基礎の石積が東面は二段、西面は四段とし上部に平の桟瓦葺とする。敷地東辺の景観を特徴づける当地特有の塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015098"},{"id":"00015096","register_sub_id":"101","register_pk":"529374","name":"岩村家住宅（旧黒岩家住宅）土蔵","kana":"いわむらけじゅうたく（きゅうくろいわけじゅうたく）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市川北字前島甲284","lat":33.50378889,"lng":133.93174167,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"39 - 0316","desc":"主屋の北に建つ土蔵造二階建の家財蔵。切妻造の置屋根形式で桟瓦葺とする。外壁は漆喰塗仕上で北面腰を瓦張とし、水切瓦を二段付す。南面中央の戸口の上に庇を付す。内部は各階、板敷の一室で、小屋組は地棟木に登梁を掛ける。屋敷地北辺の景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015096"},{"id":"00015097","register_sub_id":"101","register_pk":"529375","name":"岩村家住宅（旧黒岩家住宅）門及び駕籠部屋","kana":"いわむらけじゅうたく（きゅうくろいわけじゅうたく）もんおよびかごべや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市川北字前島甲284","lat":33.50363056,"lng":133.93185,"geo_status":"db","era":"明治前期／平成26年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"門 木造、瓦葺、間口2.0m 駕籠部屋 木造平屋建、瓦葺、建築面積11㎡","structure_material":"門 木造","registered":"2024.08.15(令和6.08.15)","register_no":"39 - 0317","desc":"主屋の南、通りに面して建つ門及び駕籠部屋。門は一間一戸切妻造桟瓦葺の腕木門で東脇間を漆喰塗壁とし腰を竪羽目板張。東に接続する駕籠部屋は切妻造桟瓦葺の東西棟。西側土間に戸口を設け、南と東に窓を開け庇を付す。通り沿いに格式ある屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015097"},{"id":"00003162","register_sub_id":"101","register_pk":"104152","name":"大西家住宅主屋","kana":"おおにしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡奈半利町甲105","lat":33.38408425,"lng":134.03762715,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階一部平屋及び地下1階建、瓦葺、建築面積89㎡","structure_material":"木造2階一部平屋及び地下1階建","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0066","desc":"漁港を見下ろす高台に建つ。桁行４間半梁間４間規模，東西棟，入母屋造，桟瓦葺の地階付木造２階建で，石造の地階を漁具置き場，１階を住居部，２階を座敷とした階層構成をとる。外壁北西面に４段の水切瓦を付け，隅部を剣先状に仕上げている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003162"},{"id":"00003015","register_sub_id":"101","register_pk":"104005","name":"尾崎家住宅蔵","kana":"おざきけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県香南市野市町西野1999","lat":33.5612322,"lng":133.69551108,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"39 － 0065","desc":"桁行３間，梁間２間規模，桟瓦葺，切妻造置屋根の平入，２階建土蔵で，土佐土蔵の特徴でもある水切り瓦２段を廻す。墨書から建築年と「大工島内光義，左官田村亀次」が知られ，東西妻の「波と雲に龍」の鏝絵の作者が判明している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003015"},{"id":"00003753","register_sub_id":"101","register_pk":"104743","name":"川田家住宅離れ","kana":"かわだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡田野町2165","lat":33.42644556,"lng":134.00745664,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0110","desc":"主屋の北方に位置し，東西棟で建つ。桁行４間半梁間２間規模，切妻造，桟瓦葺の木造平屋建で，南面全面に下屋を差し掛ける。内部は床付き４畳半と押入付き４畳半の２室構成とし，南面に内縁を付ける。風呂及び便所とともに昭和初期の屋敷構えを構成する要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003753"},{"id":"00003754","register_sub_id":"101","register_pk":"104744","name":"川田家住宅風呂及び便所","kana":"かわだけじゅうたくふろおよびべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県安芸郡田野町2165","lat":33.42647383,"lng":134.00736797,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0111","desc":"主屋の北方，蔵と離れの間に位置し，南北棟で建つ。桁行３間半梁間１間半規模，切妻造，桟瓦葺の木造平屋建で，南方１間半分を外便所に充て，脱衣所を挟んで北方に浴室を配置する。腰簓子下見，上部真壁造とした丁寧な造作の建物で，裏庭空間の主要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003754"},{"id":"00009225","register_sub_id":"101","register_pk":"164778","name":"旧柏原家住宅表門","kana":"きゅうかしわばらけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡安田町安田字東新町1674-1他","lat":33.43741171,"lng":133.9800837,"geo_status":"db","era":"昭和前期／平成22年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口2.0m","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地の北辺、東西の土塀から後方に控えて東西棟で建つ薬医門。間口2メートルに本柱を立て、冠木を渡して女梁を受け、控柱との間に男梁を架ける。切妻造桟瓦葺で破風に鰭付きの懸魚を飾り、開き戸にケヤキ1枚板を張る。良材を用いた端正なつくりの表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009225"},{"id":"00009224","register_sub_id":"101","register_pk":"164777","name":"旧柏原家住宅主屋及び離れ","kana":"きゅうかしわばらけじゅうたくしゅおくおよびはなれ","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡安田町安田字東新町1674-1他","lat":33.43733319,"lng":133.98004563,"geo_status":"db","era":"昭和前期／平成22年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積167㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"北側敷地の中央に北面して建ち、主屋の西側に離れを附属する。木造平屋建、建築面積167平方メートル、主屋、離れとも入母屋造桟瓦葺。主屋は正面中央に式台玄関を構え、主屋西側の座敷2室と、離れ北室に座敷飾りを備える。洗練されたつくりの和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009224"},{"id":"00009226","register_sub_id":"101","register_pk":"164779","name":"旧柏原家住宅東土塀及び西土塀","kana":"きゅうかしわばらけじゅうたくひがしどべいおよびにしどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡安田町安田字東新町1674-1他","lat":33.43743551,"lng":133.98004682,"geo_status":"db","era":"昭和前期／平成22年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土塀、瓦葺、総延長17m","structure_material":"土塀","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"表門の東西に折曲がりに延びる塀で、高さ2.1メートル、長さは東側5.5メートル西側11.5メートルで、切妻造桟瓦葺。50センチメートル大の自然石を積上げて基礎とし、壁面を土佐漆喰で仕上げる。高知県内の邸宅に見られるつくりで、地方的特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009226"},{"id":"00006953","register_sub_id":"101","register_pk":"107935","name":"旧門脇家住宅主屋","kana":"きゅうかどわきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県高岡郡四万十町大正32-1","lat":33.18361848,"lng":132.97295617,"geo_status":"db","era":"明治8／平成2移築","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造平屋建、茅葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"39 － 0252","desc":"南面する入母屋造茅葺の民家で、もとは山間の下津井集落に所在。桁行５間梁間３間半規模で、桁行に大きく３分し、トコ付の１０畳間を右手に、中央に２畳と３畳を前後に配し、左手を入口土間と囲炉裏間とする。当地域における山村民家の特色を備える民家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006953"},{"id":"00015102","register_sub_id":"101","register_pk":"529380","name":"旧小松家住宅井戸","kana":"きゅうこまつけじゅうたくいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県香南市赤岡町字本町北ノ東772-1","lat":33.54148056,"lng":133.72598333,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、面積14㎡","structure_material":"石造","registered":"2024.08.15(令和6.08.15)","register_no":"39 - 0322","desc":"主屋北に位置し酒造用の良水を供した井戸。深さ９メートル、円筒形井筒を砂岩切石で積み、井戸枠は砂岩板四枚を合欠に組み鉄の丸太枘を入れる。井戸廻りは御影石を敷並べ、周囲の溝は縁を青石、底は煉瓦敷。東方の煉瓦積排水枡とともに一連の構えを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015102"},{"id":"00015101","register_sub_id":"101","register_pk":"529379","name":"旧小松家住宅表門及び煉瓦塀","kana":"きゅうこまつけじゅうたくおもてもんおよびれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市赤岡町字本町北ノ東772-1","lat":33.54131111,"lng":133.72587222,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"表門 木造、瓦葺、間口1.3m、煉瓦塀 煉瓦造、瓦葺、総延長24m","structure_material":"表門 木造","registered":"2024.08.15(令和6.08.15)","register_no":"39 - 0321","desc":"主屋から西へ延び、北へ折れて土蔵南面に取り付く煉瓦塀である。南面の主屋際に腕木門の表門、西面の土蔵寄りにアーチ門を開く。イギリス積とし、内側に控壁を配す。西面は軒蛇腹を迫出し、上部に軒唐草の桟瓦を葺く。街道沿いに重厚な景観を形成する煉瓦塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015101"},{"id":"00015099","register_sub_id":"101","register_pk":"529377","name":"旧小松家住宅店舗兼主屋","kana":"きゅうこまつけじゅうたくてんぽけんおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市赤岡町字本町北ノ東772-1","lat":33.54136667,"lng":133.72604444,"geo_status":"db","era":"明治前期／大正15年・令和4年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積224㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"39 - 0319","desc":"旧土佐街道に南面して建つ、元酒造業兼煉瓦製造販売の店舗兼主屋である。間口一杯に庇を通し、二階外壁を弁柄漆喰塗とする。西に落棟で座敷と次の間が接続する。正面土間ミセ、東の通り土間、裏の窯屋を自家製の煉瓦敷とする。街道沿いに独特の景観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015099"},{"id":"00015100","register_sub_id":"101","register_pk":"529378","name":"旧小松家住宅土蔵","kana":"きゅうこまつけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市赤岡町字本町北ノ東772-1","lat":33.54142778,"lng":133.7259,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"39 - 0320","desc":"主屋の西に建つ、土蔵造二階建の家財蔵である。切妻造の南北棟で桟瓦葺とする。外壁は白漆喰塗で水切瓦を二段付け、西面は腰を竪板張とする。南面に戸口を設け瓦庇を付す。内部は各階板敷とし、小屋は地棟に登梁を架ける形式。敷地西面の景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015100"},{"id":"00011010","register_sub_id":"101","register_pk":"208980","name":"旧弘瀬家住宅主屋","kana":"きゅうひろせけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡奈半利町字竪横町乙1670","lat":33.424801,"lng":134.021526,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋一部2階建、瓦葺、建築面積106㎡","structure_material":"木造平屋一部2階建","registered":"2016.02.25(平成28.02.25)","register_no":"39-0290","desc":"南北に通る街道西側にある。東面して建つ主屋は木造つし二階建の店舗兼用住宅で、屋根は切妻造、桟瓦葺、正面と背面に下屋庇を設ける。正面の細長い縦格子窓、土佐漆喰に水切瓦をつけた妻面などに地域特有の伝統形式を呈し、良好な町並み景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011010"},{"id":"00011008","register_sub_id":"101","register_pk":"208978","name":"旧三浦家住宅表門及び塀","kana":"きゅうみうらけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県須崎市青木町1763","lat":33.38987394,"lng":133.28945701,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"表門 木造、瓦葺、間口1.8m 塀 木造、瓦葺、総延長9.3m","structure_material":"表門 木造","registered":"2016.02.25(平成28.02.25)","register_no":"39-0288","desc":"店舗側の東に控柱を備えた腕木門形式の表門を構え、西に柱間七間の木造の塀を延ばし、桟瓦葺屋根を架ける。ケヤキの良材を用いた門、亀甲石積の塀の基礎、塀の横長窓に名栗仕上げの化粧桟を入れるなど、全体に丁寧なつくりで、敷地南辺の景観を良好に整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011008"},{"id":"00011006","register_sub_id":"101","register_pk":"208976","name":"旧三浦家住宅蔵","kana":"きゅうみうらけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県須崎市青木町7-1","lat":33.389966,"lng":133.28954,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"鉄筋コンクリート造2階建、瓦葺、建築面積23㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"39-0286","desc":"店舗の北側に隣接する。鉄筋コンクリート造の二階建、南北棟の切妻造で、小屋は木造トラス組である。桟瓦葺屋根は東に右瓦、西に左瓦を用いる。平入で、一階西面に庇を設け、扉口や東面窓に金属扉を用い、壁面を土佐漆喰で仕上げるなど、独特なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011006"},{"id":"00011005","register_sub_id":"101","register_pk":"208975","name":"旧三浦家住宅主屋","kana":"きゅうみうらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県須崎市青木町7-1","lat":33.389968,"lng":133.289432,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積126㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"39-0285","desc":"店舗の西に接続している。木造平屋建、東西棟の切妻造で南と北に下屋庇をつける。南面の東に玄関を設け、南面に床と棚のある八畳座敷を配する。右瓦と左瓦を葺き分けた桟瓦葺屋根で漆喰を用いて丁寧に瓦を留め、簡明な外観になるが、内部では良材を多用する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011005"},{"id":"00011007","register_sub_id":"101","register_pk":"208977","name":"旧三浦家住宅離れ","kana":"きゅうみうらけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県須崎市青木町7-1","lat":33.39006,"lng":133.289533,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"39-0287","desc":"敷地北奥にあり、主屋と廊下で接続している。木造平屋建、東西棟の寄棟造で、南面と西面に下屋庇を廻し、桟瓦葺とする。小屋はキングポストトラス組である。内部は活用に合わせて改造されているが、実業家の大規模屋敷構成の近代的有り様を知ることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011007"},{"id":"00011009","register_sub_id":"101","register_pk":"208979","name":"旧三浦家住宅ブロック塀","kana":"きゅうみうらけじゅうたくぶろっくべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県須崎市青木町1763","lat":33.3899683,"lng":133.28958101,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"コンクリートブロック造、瓦葺、延長8.2m、潜り付","structure_material":"コンクリートブロック造","registered":"2016.02.25(平成28.02.25)","register_no":"39-0289","desc":"店舗の東面から北に延びる八・二メートルの塀。コンクリート基礎に直方体のセメント製ブロックを一一段に積み上げ、頂部に桟瓦葺屋根を架ける。北寄りに潜戸を設け、敷地側には物置を設け屋根を延ばす。屋敷景観を整える近代らしい形式の塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011009"},{"id":"00001648","register_sub_id":"101","register_pk":"102638","name":"旧味元家住宅主屋","kana":"きゅうみもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県南国市岡豊町八幡1099-1","lat":33.5967988,"lng":133.62348749,"geo_status":"db","era":"天保3／平成3移築","year":1832,"year_source":"db","year_min":1832,"year_max":1832,"year_label":null,"structure":"木造平屋建、茅葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"39 － 0007","desc":"高知県中西部，東津野村の山間地に営まれた入母屋造，茅葺，広間型の民家。土間にはコウゾ蒸し用の窯が設置され，茶の間屋根裏をコウゾの貯蔵場とするなど，和紙原料栽培を生業とした山間地の生活を物語る。平成３年に高知県立歴史民俗資料館に移築された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001648"},{"id":"00014968","register_sub_id":"101","register_pk":"519228","name":"旧森田家住宅表門","kana":"きゅうもりたけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市野市町兎田字小林谷482-1他","lat":33.57311111,"lng":133.72219722,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口2.4m、袖塀付","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"39 - 0311","desc":"敷地南面の東寄りに建つ表門。一間一戸の薬医門で南北に袖塀を付す。屋根は起りのある切妻造桟瓦葺とする。主要部材は木太く豪壮なつくりで、控柱は腰貫で固め、門口に両開戸を吊る。通りに面して建ち、西に続く土塀とともに地域の歴史的な景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014968"},{"id":"00014966","register_sub_id":"101","register_pk":"519226","name":"旧森田家住宅主屋","kana":"きゅうもりたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市野市町兎田字小林谷482-1他","lat":33.57326389,"lng":133.72216667,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積206㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"39 - 0309","desc":"高知平野東部の農村集落に位置する旧家の主屋。南面中央に入母屋屋根を重ねた式台玄関を突出。西は田の字に部屋を配し、東は座敷で部屋境に大振りな欄間彫刻を飾り、縁側下屋に丸太の化粧桁を用いるなど豪壮なつくり。武家由来の格式を備えた近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014966"},{"id":"00014967","register_sub_id":"101","register_pk":"519227","name":"旧森田家住宅土蔵","kana":"きゅうもりたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市野市町兎田字小林谷482-1他","lat":33.57333611,"lng":133.72200833,"geo_status":"db","era":"明治後期／大正後期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"39 - 0310","desc":"主屋の西側に東面して建つ家財蔵。二階建で置屋根は切妻造桟瓦葺とする。漆喰塗仕上の外壁は土台を塗込めずに現しとし、水切瓦を廻して上部に鉢巻を付す。建築後まもなく南半を増築し、内部は各階二室に分ける。屋根に左桟瓦を用いるなど地域性豊かな土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014967"},{"id":"00014971","register_sub_id":"101","register_pk":"519231","name":"旧森田家住宅土塀","kana":"きゅうもりたけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市野市町兎田字小林谷482-1他","lat":33.55371111,"lng":132.65542778,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土塀、瓦葺、総延長20m","structure_material":"土塀","registered":"2024.03.06(令和6.03.06)","register_no":"39 - 0314","desc":"表門の西側から主屋の式台玄関の東西脇に廻り、全体で枡形状経路をつくる総延長二〇メートルの塀。大きな自然石を用いた豪壮な石組に土塀を建て、屋根は桟瓦葺とする。外壁は旧は漆喰仕上。主屋玄関廻りに表門、脇門、塀重門と一体で武家風の構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014971"}];
